/* eslint-disable react-hooks/set-state-in-effect, no-unused-vars, react-hooks/purity, no-func-assign, react-hooks/exhaustive-deps */
import { useEffect, useMemo, useRef, useState } from "react";
import "./MobileApp.css";
import MarkdownMessage from "../components/MarkdownMessage.jsx";

// The route remains frozen; the mobile AI surface is replaced below.
AIHome = (props) => <MobileChatShell {...props} user={props.user || readUser()} />;
const baseRouteWithContext = routeWithContext;
function mobileRouteWithIds(path) { const result = baseRouteWithContext(path); const [, search = ""] = path.split("?"); const params = new URLSearchParams(search); return { ...result, chapterId: params.get("chapterId") || "", knowledgeId: params.get("knowledgeId") || "" }; }
routeWithContext = mobileRouteWithIds;

const API_BASE = "/api";

function MobileAIChatV73({ route, course, user }) {
  const exam = route.space === EXAM;
  const courseLabel = course ? courseName(course) : "普通 AI";
  const subjectLabel = exam ? (EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject) : courseLabel;
  const query = () => { const q = new URLSearchParams({ username: user.username }); if (exam) { q.set("subject_key", route.subject); q.set("exam_subject", route.subject); q.set("subject", subjectLabel); } else if (course) { q.set("course", courseLabel); q.set("course_id", courseId(course)); q.set("subject", courseLabel); } return q; };
  const context = exam ? { space: "11408", subject: route.subject, chapter: route.chapter || "", knowledge: route.knowledge || "" } : course ? { space: "course", courseId: courseId(course), courseName: courseLabel, learningMode: route.mode, chapterId: route.chapterId || route.chapter || "", knowledgeId: route.knowledgeId || route.knowledge || "", chapter: route.chapter || "", knowledge: route.knowledge || "" } : { space: "general" };
  const [sessions, setSessions] = useState([]); const [sessionId, setSessionId] = useState(null); const [messages, setMessages] = useState([]); const [input, setInput] = useState(""); const [loading, setLoading] = useState(false); const [historyLoading, setHistoryLoading] = useState(true); const [error, setError] = useState(""); const [sheetMessage, setSheetMessage] = useState(null); const [editingId, setEditingId] = useState(""); const [editingText, setEditingText] = useState(""); const [uploading, setUploading] = useState(false); const [uploadItem, setUploadItem] = useState(null); const messagesRef = useRef(null); const inputRef = useRef(null); const fileRef = useRef(null); const holdTimer = useRef(null);
  const loadHistory = async () => { setHistoryLoading(true); try { const r = await fetch(`${API_BASE}/chat/history?${query()}`); const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.detail || "历史对话加载失败"); setSessions(safeArray(d.sessions).filter((session) => chatSessionMatchesScope(session, route, course))); } catch (e) { setSessions([]); setError(e.message || "历史对话加载失败"); } finally { setHistoryLoading(false); } };
  const loadSession = async (id) => { try { const r = await fetch(`${API_BASE}/chat/sessions/${id}?${query()}`); const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.detail || "打开对话失败"); setSessionId(d.session?.id || id); setMessages(safeArray(d.messages)); setSheetMessage(null); } catch (e) { setError(e.message || "打开对话失败"); } };
  const startNewConversation = () => { setSessionId(null); setMessages([]); setInput(""); setUploadItem(null); setSheetMessage(null); setEditingId(""); setError(""); window.requestAnimationFrame(() => inputRef.current?.focus()); };
  useEffect(() => { setSessionId(null); setMessages([]); setInput(""); setUploadItem(null); loadHistory(); }, [route.space, route.subject, route.courseId, route.mode, route.chapter, route.knowledge, user.username]);
  useEffect(() => { if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight; }, [messages, loading]);
  const send = async (value = input, options = {}) => { const text = String(value || "").trim(); if (!text || loading) return; setLoading(true); setError(""); setInput(""); const localId = `mobile-user-${Date.now()}`; setMessages((prev) => [...prev, { id: localId, role: "user", content: text, created_at: new Date().toISOString() }]); try { const payload = { username: user.username, message: text, subject: exam ? subjectLabel : course ? courseLabel : "general", course: course ? courseLabel : "general", session_id: sessionId, branch_id: options.branchId || "", edit_source_message_id: options.sourceId ? Number(options.sourceId) || null : undefined, knowledge_context: context, material_ids: uploadItem?.material_id ? [uploadItem.material_id] : [] }; if (exam) Object.assign(payload, { subject_key: route.subject, exam_subject: route.subject }); const r = await fetch(`${API_BASE}/chat`, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify(payload) }); const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.detail || "AI 服务调用失败"); setSessionId(d.session?.id || d.session_id || sessionId); setMessages((prev) => [...prev.map((m) => m.id === localId ? { ...m, id: d.user_message_id || m.id, branch_id: d.branch_id || "" } : m), { id: d.assistant_message_id || `mobile-ai-${Date.now()}`, role: "assistant", content: d.answer || "", references: d.references || [], created_at: new Date().toISOString() }]); setUploadItem(null); await loadHistory(); } catch (e) { setError(e.message || "AI 服务调用失败"); } finally { setLoading(false); } };
  const upload = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; setUploading(true); setError(""); setUploadItem({ filename: file.name, parse_status: "uploading", file_size: file.size }); try { const form = new FormData(); form.append("file", file); form.append("username", user.username); form.append("subject", exam ? subjectLabel : courseLabel); form.append("save_to_materials", "true"); const r = await fetch(`${API_BASE}/materials/upload`, { method: "POST", credentials: "include", body: form }); const d = await r.json().catch(() => ({})); if (!r.ok) throw new Error(d.detail || "文件上传失败"); setUploadItem({ ...d, material_id: d.material_id || d.id, filename: d.filename || d.original_filename || file.name, file_size: d.file_size || file.size, parse_status: d.parse_status || "pending" }); } catch (e) { setUploadItem({ filename: file.name, parse_status: "failed" }); setError(e.message || "文件上传失败"); } finally { setUploading(false); } };
  const copy = async (message) => { try { await navigator.clipboard?.writeText(message.content || ""); setError("已复制"); } catch { setError("复制失败"); } setSheetMessage(null); };
  const openEdit = (message) => { setEditingId(String(message.id)); setEditingText(message.content || ""); setSheetMessage(null); };
  const commitEdit = async (message) => { const text = editingText.trim(); if (!text) return; setEditingId(""); setEditingText(""); await send(text, { sourceId: message.id, branchId: message.branch_id || "" }); };
  const removeLocal = (message) => { setMessages((prev) => prev.filter((item) => item.id !== message.id)); setSheetMessage(null); setError("已从当前移动会话隐藏；PC 历史未删除（后端没有消息级删除接口）。"); };
  const beginHold = (message) => { holdTimer.current = window.setTimeout(() => setSheetMessage(message), 550); };
  const endHold = () => { if (holdTimer.current) window.clearTimeout(holdTimer.current); };
  const title = exam ? "11408 AI助手" : course ? "课程 AI助手" : "普通 AI助手";
  const contextLines = exam ? [subjectLabel, route.chapter || "", route.knowledge || ""].filter(Boolean) : course ? [courseLabel, route.chapterId || route.chapter || "", route.knowledgeId || route.knowledge || ""].filter(Boolean) : [];
  return <div className="page mobile-ai-page"><PageHeading eyebrow={exam ? "11408 AI" : course ? `课程 AI · ${MODE_LABELS[route.mode]}` : "普通 AI"} title="AI助手" description="历史、消息和上下文按当前空间自动隔离。" /><section className="mobile-ai-context"><strong>{title}</strong>{contextLines.length ? <span>{contextLines.join(" · ")}</span> : !exam && !course ? <span>独立 AI 服务</span> : null}</section><section className="mobile-ai-history"><div className="mobile-ai-history-head"><strong>历史对话</strong><button type="button" onClick={startNewConversation}>新对话</button></div>{historyLoading ? <small>正在读取历史…</small> : sessions.length ? sessions.slice(0, 8).map((s) => <button type="button" key={s.id} className={sessionId === s.id ? "is-active" : ""} onClick={() => loadSession(s.id)}><span>{s.title || "未命名对话"}</span><small>{s.subject || s.exam_subject || "AI"}</small></button>) : <small>暂无历史对话</small>}</section><div className="mobile-ai-messages" ref={messagesRef}>{messages.length === 0 && !loading ? <div className="mobile-ai-empty"><Icon name="ai" /><strong>开始提问</strong><span>当前上下文会自动携带。</span></div> : messages.map((message) => <article key={`${message.role}-${message.id}`} className={`mobile-ai-message ${message.role === "user" ? "is-user" : "is-assistant"}`} onContextMenu={(event) => { if (message.role === "user") { event.preventDefault(); setSheetMessage(message); } }} onTouchStart={() => message.role === "user" && beginHold(message)} onTouchEnd={endHold} onTouchCancel={endHold}><div className="mobile-ai-message-role">{message.role === "user" ? "我" : "AI"}</div>{editingId === String(message.id) ? <div className="mobile-ai-edit"><textarea value={editingText} onChange={(event) => setEditingText(event.target.value)} autoFocus /><div><button type="button" onClick={() => setEditingId("")}>取消</button><button type="button" onClick={() => commitEdit(message)}>提交</button></div></div> : <div className="mobile-ai-message-body"><MarkdownMessage content={message.content || ""} /><small>{message.references?.length ? `包含 ${message.references.length} 条参考资料` : ""}</small></div>}</article>)}</div>{uploadItem && <div className={`mobile-upload-card is-${uploadItem.parse_status}`}><strong>{uploadItem.filename}</strong><span>{uploadItem.parse_status === "uploading" ? "上传中…" : uploadItem.parse_status === "pending" ? "已上传，等待解析" : uploadItem.parse_status === "failed" ? "上传失败" : "已上传，可随问题发送"}</span></div>}{error && <div className="inline-error">{error}</div>}<form className="mobile-ai-composer" onSubmit={(event) => { event.preventDefault(); send(); }}><input ref={fileRef} type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.pptx,.txt,.md,.markdown,.py,.java,.c,.cpp,.h,.hpp,.js,.jsx,.ts,.tsx,.html,.htm,.css,.json,.xml,.yaml,.yml,.sql,.sh,.bash,.go,.rs,.php,.rb" onChange={upload} /><button type="button" className="mobile-ai-tool" onClick={() => fileRef.current?.click()} disabled={uploading}>{uploading ? "…" : "＋"}</button><textarea ref={inputRef} value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); send(); } }} placeholder="输入你的问题…" rows={1} /><button type="submit" className="primary-button" disabled={loading || !input.trim()}>发送</button></form>{sheetMessage && <div className="mobile-action-sheet-backdrop" onClick={() => setSheetMessage(null)}><section className="mobile-action-sheet" onClick={(event) => event.stopPropagation()}><div className="sheet-handle" /><strong>消息操作</strong><button type="button" onClick={() => copy(sheetMessage)}>复制</button><button type="button" onClick={() => openEdit(sheetMessage)}>编辑</button><button type="button" onClick={() => { setSheetMessage(null); send(sheetMessage.content, { sourceId: sheetMessage.id, branchId: sheetMessage.branch_id || "" }); }}>重新生成</button><button type="button" onClick={() => { setSheetMessage(null); send(sheetMessage.content, { sourceId: sheetMessage.id, branchId: `mobile-branch-${Date.now()}` }); }}>创建分支</button><button type="button" className="is-danger" onClick={() => removeLocal(sheetMessage)}>删除</button><button type="button" className="secondary-button" onClick={() => setSheetMessage(null)}>取消</button></section></div>}</div>;
}

function MobileChatShell({ route, course, user }) {
  const exam = route.space === EXAM;
  const isCourse = Boolean(course) && !exam;
  const courseLabel = isCourse ? courseName(course) : "";
  const subjectLabel = exam ? (EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject || "11408") : "";
  const scope = exam ? "exam11408" : isCourse ? "course" : "general";
  const context = exam
    ? { scope, examSubject: route.subject || "", subjectName: subjectLabel, chapterId: route.chapterId || "", chapterName: route.chapter || "", knowledgeId: route.knowledgeId || "", knowledgeName: route.knowledge || "" }
    : isCourse
      ? { scope, courseId: courseId(course), courseName: courseLabel, learningMode: route.mode || "daily", chapterId: route.chapterId || "", chapterName: route.chapter || "", knowledgeId: route.knowledgeId || "", knowledgeName: route.knowledge || "" }
      : { scope };
  const scopeKey = JSON.stringify(context);
  const [sessions, setSessions] = useState([]);
  const [sessionId, setSessionId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [status, setStatus] = useState({ type: "loading", message: "" });
  const [sheetMessage, setSheetMessage] = useState(null);
  const [editingId, setEditingId] = useState("");
  const [editingText, setEditingText] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadItem, setUploadItem] = useState(null);
  const messagesRef = useRef(null);
  const inputRef = useRef(null);
  const fileRef = useRef(null);
  const holdTimer = useRef(null);

  const scopeQuery = () => {
    const query = new URLSearchParams({ username: user?.username || "" });
    if (exam) {
      query.set("subject_key", route.subject || "");
      query.set("exam_subject", route.subject || "");
      query.set("subject", subjectLabel);
    } else if (isCourse) {
      query.set("course", courseLabel);
      query.set("course_id", courseId(course));
      query.set("subject", courseLabel);
    } else {
      query.set("course", "general");
      query.set("subject", "general");
    }
    return query;
  };
  const loadHistory = async () => {
    setStatus({ type: "loading", message: "" });
    try {
      const response = await fetch(`${API_BASE}/chat/history?${scopeQuery().toString()}`, { credentials: "include" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || "历史对话加载失败");
      const filtered = safeArray(data.sessions).filter((session) => chatSessionMatchesScope(session, route, course));
      setSessions(filtered);
      setStatus({ type: "success", message: "" });
    } catch (error) {
      setSessions([]);
      setStatus({ type: "error", message: error.message || "历史对话加载失败" });
    }
  };
  const loadSession = async (id) => {
    if (!id) return;
    setStatus({ type: "loading", message: "" });
    try {
      const response = await fetch(`${API_BASE}/chat/sessions/${encodeURIComponent(id)}?${scopeQuery().toString()}`, { credentials: "include" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || "打开对话失败");
      setSessionId(data.session?.id || id);
      setMessages(safeArray(data.messages));
      setHistoryOpen(false);
      setStatus({ type: "success", message: "" });
      requestAnimationFrame(() => { if (messagesRef.current) messagesRef.current.scrollTop = 0; });
    } catch (error) {
      setStatus({ type: "error", message: error.message || "打开对话失败" });
    }
  };
  const startNewConversation = () => {
    setSessionId(null);
    setMessages([]);
    setInput("");
    setUploadItem(null);
    setHistoryOpen(false);
    setSheetMessage(null);
    setEditingId("");
    setStatus({ type: "success", message: "" });
    requestAnimationFrame(() => inputRef.current?.focus());
  };
  useEffect(() => {
    setSessionId(null);
    setMessages([]);
    setHistoryOpen(false);
    loadHistory();
    requestAnimationFrame(() => inputRef.current?.focus());
  }, [scopeKey, user?.username]);
  useEffect(() => {
    const viewport = window.visualViewport;
    if (!viewport) return undefined;
    const update = () => document.documentElement.style.setProperty("--mobile-keyboard-height", `${Math.max(0, window.innerHeight - viewport.height)}px`);
    viewport.addEventListener("resize", update);
    viewport.addEventListener("scroll", update);
    update();
    return () => { viewport.removeEventListener("resize", update); viewport.removeEventListener("scroll", update); };
  }, []);
  useEffect(() => {
    const node = messagesRef.current;
    if (!node) return;
    const nearBottom = node.scrollHeight - node.scrollTop - node.clientHeight < 120;
    if (nearBottom) node.scrollTop = node.scrollHeight;
  }, [messages, loading]);
  const send = async (value = input, options = {}) => {
    const text = String(value || "").trim();
    if (!text || loading || !user?.username) return;
    setLoading(true);
    setStatus({ type: "success", message: "" });
    setInput("");
    const localId = `mobile-user-${Date.now()}`;
    setMessages((previous) => [...previous, { id: localId, role: "user", content: text, created_at: new Date().toISOString() }]);
    const payload = {
      username: user.username,
      message: text,
      subject: exam ? subjectLabel : isCourse ? courseLabel : "general",
      course: isCourse ? courseLabel : "general",
      session_id: sessionId,
      branch_id: options.branchId || "",
      edit_source_message_id: options.sourceId ? Number(options.sourceId) || null : undefined,
      knowledge_context: context,
      material_ids: uploadItem?.material_id ? [uploadItem.material_id] : [],
    };
    if (exam) Object.assign(payload, { subject_key: route.subject, exam_subject: route.subject });
    try {
      const response = await fetch(`${API_BASE}/chat`, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify(payload) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || "AI 服务调用失败");
      const nextSessionId = data.session?.id || data.session_id || sessionId;
      setSessionId(nextSessionId);
      setMessages((previous) => [...previous.map((message) => message.id === localId ? { ...message, id: data.user_message_id || message.id, branch_id: data.branch_id || "" } : message), { id: data.assistant_message_id || `mobile-ai-${Date.now()}`, role: "assistant", content: data.answer || data.content || "", references: data.references || [], created_at: new Date().toISOString() }]);
      setUploadItem(null);
      await loadHistory();
    } catch (error) {
      setMessages((previous) => previous.filter((message) => message.id !== localId));
      setStatus({ type: "error", message: error.message || "AI 服务调用失败" });
    } finally {
      setLoading(false);
    }
  };
  const upload = async (event) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setUploading(true);
    setUploadItem({ filename: file.name, parse_status: "uploading" });
    try {
      const form = new FormData();
      form.append("file", file);
      form.append("username", user.username);
      form.append("subject", exam ? subjectLabel : courseLabel || "general");
      form.append("save_to_materials", "true");
      const response = await fetch(`${API_BASE}/materials/upload`, { method: "POST", credentials: "include", body: form });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || "文件上传失败");
      setUploadItem({ ...data, material_id: data.material_id || data.id, filename: data.filename || data.original_filename || file.name, parse_status: data.parse_status || "pending" });
    } catch (error) {
      setUploadItem({ filename: file.name, parse_status: "failed" });
      setStatus({ type: "error", message: error.message || "文件上传失败" });
    } finally { setUploading(false); }
  };
  const copy = async (message) => { try { await navigator.clipboard?.writeText(message.content || ""); setStatus({ type: "success", message: "已复制" }); } catch { setStatus({ type: "error", message: "复制失败" }); } setSheetMessage(null); };
  const openEdit = (message) => { setEditingId(String(message.id)); setEditingText(message.content || ""); setSheetMessage(null); };
  const commitEdit = async (message) => { const text = editingText.trim(); if (!text) return; setEditingId(""); setEditingText(""); await send(text, { sourceId: message.id, branchId: message.branch_id || "" }); };
  const beginHold = (message) => { holdTimer.current = window.setTimeout(() => setSheetMessage(message), 550); };
  const endHold = () => { if (holdTimer.current) window.clearTimeout(holdTimer.current); };
  const contextLabel = exam ? [subjectLabel, route.chapter, route.knowledge].filter(Boolean).join(" · ") : isCourse ? [courseLabel, route.chapter, route.knowledge].filter(Boolean).join(" · ") : "普通 AI";
  const title = exam ? "11408 AI助手" : isCourse ? "课程 AI助手" : "普通 AI助手";
  const backPath = exam ? `/m/exam11408/${encodeURIComponent(route.subject)}/home` : isCourse ? coursePath(route.mode || "daily", courseId(course), "/home") : "/m";
  return <div className="mobile-chat-page">
    <header className="mobile-chat-header"><button type="button" className="mobile-chat-back" onClick={() => goBack(backPath)}>‹ 返回</button><div><strong>{title}</strong><span>{contextLabel}</span></div><button type="button" className="mobile-chat-history-button" onClick={() => setHistoryOpen((value) => !value)}>历史</button></header>
    {historyOpen && <section className="mobile-chat-history"><div className="mobile-chat-history-head"><strong>历史对话</strong><button type="button" onClick={startNewConversation}>新对话</button></div>{status.type === "loading" ? <small>正在读取历史…</small> : status.type === "error" ? <><small>{status.message}</small><button type="button" className="text-button" onClick={loadHistory}>点击重试</button></> : sessions.length ? sessions.map((session) => <button type="button" key={session.id} onClick={() => loadSession(session.id)}><span>{session.title || "未命名对话"}</span><small>{session.created_at ? new Date(session.created_at).toLocaleString("zh-CN") : ""}</small></button>) : <small>暂无历史对话</small>}</section>}
    <div className="mobile-chat-messages" ref={messagesRef}>{messages.length === 0 && !loading ? <div className="mobile-ai-empty"><Icon name="ai" /><strong>开始提问</strong><span>{contextLabel}</span></div> : messages.map((message) => <article key={`${message.role}-${message.id}`} className={`mobile-ai-message ${message.role === "user" ? "is-user" : "is-assistant"}`} onContextMenu={(event) => { if (message.role === "user") { event.preventDefault(); setSheetMessage(message); } }} onTouchStart={() => message.role === "user" && beginHold(message)} onTouchEnd={endHold} onTouchCancel={endHold}><div className="mobile-ai-message-role">{message.role === "user" ? "我" : "AI"}</div>{editingId === String(message.id) ? <div className="mobile-ai-edit"><textarea value={editingText} onChange={(event) => setEditingText(event.target.value)} autoFocus /><div><button type="button" onClick={() => setEditingId("")}>取消</button><button type="button" onClick={() => commitEdit(message)}>提交</button></div></div> : <div className="mobile-ai-message-body"><MarkdownMessage content={message.content || ""} /></div>}</article>)}{loading && <div className="mobile-chat-loading">AI 正在思考…</div>}</div>
    {uploadItem && <div className={`mobile-upload-card is-${uploadItem.parse_status}`}><strong>{uploadItem.filename}</strong><span>{uploadItem.parse_status === "uploading" ? "上传中…" : uploadItem.parse_status === "failed" ? "上传失败" : "已上传，可随问题发送"}</span></div>}
    {status.type === "error" && !historyOpen && <div className="mobile-chat-error">{status.message}<button type="button" onClick={loadHistory}>重试</button></div>}
    <form className="mobile-chat-composer" onSubmit={(event) => { event.preventDefault(); send(); }}><input ref={fileRef} type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.pptx,.txt,.md,.markdown,.py,.java,.c,.cpp,.h,.hpp,.js,.jsx,.ts,.tsx,.html,.htm,.css,.json,.xml,.yaml,.yml,.sql,.sh,.bash,.go,.rs,.php,.rb" onChange={upload} /><button type="button" className="mobile-ai-tool" onClick={() => fileRef.current?.click()} disabled={uploading}>{uploading ? "…" : "＋"}</button><textarea ref={inputRef} value={input} onChange={(event) => setInput(event.target.value)} onInput={(event) => { event.currentTarget.style.height = "auto"; event.currentTarget.style.height = `${Math.min(event.currentTarget.scrollHeight, 120)}px`; }} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); send(); } }} placeholder="输入你的问题…" rows={1} /><button type="submit" className="primary-button" disabled={loading || !input.trim()}>发送</button></form>
    {sheetMessage && <div className="mobile-action-sheet-backdrop" onClick={() => setSheetMessage(null)}><section className="mobile-action-sheet" onClick={(event) => event.stopPropagation()}><div className="sheet-handle" /><strong>消息操作</strong><button type="button" onClick={() => copy(sheetMessage)}>复制</button><button type="button" onClick={() => openEdit(sheetMessage)}>编辑</button><button type="button" onClick={() => { setSheetMessage(null); send(sheetMessage.content, { sourceId: sheetMessage.id, branchId: sheetMessage.branch_id || "" }); }}>重新生成</button><button type="button" onClick={() => { setSheetMessage(null); send(sheetMessage.content, { sourceId: sheetMessage.id, branchId: `mobile-branch-${Date.now()}` }); }}>创建分支</button><button type="button" className="secondary-button" onClick={() => setSheetMessage(null)}>取消</button></section></div>}
  </div>;
}
const COURSE = "course";
const EXAM = "exam";
const EXAM_SUBJECTS = [["data_structure", "数据结构"], ["computer_organization", "计算机组成原理"], ["operating_system", "操作系统"], ["computer_network", "计算机网络"]];
const MODE_LABELS = { daily: "平日学习", exam: "考前突击" };
const icons = { home: "⌂", knowledge: "◫", ai: "✦", practice: "✓", profile: "●", book: "▤", exam: "◇", lock: "⌁", user: "○", quota: "◔", shop: "□", settings: "⚙" };

function readUser() { try { return JSON.parse(localStorage.getItem("ai_study_platform_user") || "null") || {}; } catch { return {}; } }
function go(path) { window.history.pushState({}, "", path); window.dispatchEvent(new PopStateEvent("popstate")); }
function goBack(fallback) { if (window.history.length > 1) window.history.back(); else go(fallback); }
function safeArray(value) { return Array.isArray(value) ? value : []; }
function textValue(item, fields) { for (const field of fields) if (typeof item?.[field] === "string" && item[field].trim()) return item[field].trim(); return ""; }
function courseName(course) { return textValue(course, ["display_name", "course_name", "name", "course_id"]) || "未命名课程"; }
function courseId(course) { return String(course?.course_id ?? "").trim(); }
function courseLearningMode(course) { const mode = String(course?.primary_mode || course?.primaryMode || course?.mode || "daily").trim().toLowerCase(); return mode === "exam" ? "exam" : "daily"; }
function courseLearningModeLabel(course) { return course?.primary_mode_label || MODE_LABELS[courseLearningMode(course)] || "平日学习"; }
function chatSessionMatchesScope(session, route, course) { const exam = route.space === EXAM; const sessionExam = String(session?.exam_subject || session?.subject_key || "").trim(); if (exam) return sessionExam === String(route.subject || "").trim(); if (course) { const id = courseId(course); const name = courseName(course); return !sessionExam && [session?.course_id, session?.course, session?.subject].some((value) => String(value || "").trim() === id || String(value || "").trim() === name); } const values = [session?.course, session?.subject].map((value) => String(value || "").trim()); return !sessionExam && values.every((value) => !value || value === "general"); }
function routeFor(pathname) { const parts = pathname.split("/").filter(Boolean); if (parts[0] !== "m") return { page: "course-mode" }; if (parts[1] === "profile") { return { page: !parts[2] ? "profile" : parts[2] === "membership" ? "profile-membership" : parts[2] === "quota" ? "profile-quota" : parts[2] === "shop" ? "profile-shop" : "profile" }; } if (parts[1] === "ai") return { page: "ai", space: null }; if (parts[1] === "course") { if (parts[2] === "daily" || parts[2] === "exam") { const mode = parts[2]; if (!parts[3]) return { page: mode === "daily" ? "course-daily" : "course-exam", space: COURSE, mode }; const courseId = parts[3]; if (parts[4] === "task") return { page: "course-exam-task", space: COURSE, mode, courseId, taskId: parts[5] || "" }; const section = parts[4] || "home"; return { page: section === "knowledge" ? "course-knowledge" : section === "practice" ? "course-practice" : section === "plan" ? "course-plan" : section === "ai" ? "ai" : "course-home", space: COURSE, mode, courseId }; } if (parts[2]) return { page: parts[3] === "knowledge" ? "course-knowledge" : parts[3] === "practice" ? "course-practice" : parts[3] === "plan" ? "course-plan" : parts[3] === "ai" ? "ai" : "course-home", space: COURSE, mode: "daily", courseId: parts[2] }; return { page: "course-mode", space: COURSE }; } if (parts[1] === "exam11408") { if (!parts[2]) return { page: "exam-select", space: EXAM }; const subject = parts[2]; return { page: parts[3] === "chapters" ? "exam-chapters" : parts[3] === "practice" ? "exam-practice" : parts[3] === "plan" ? "exam-plan" : parts[3] === "ai" ? "exam-ai" : "exam-home", space: EXAM, subject }; } return { page: "course-mode" }; }
function routeWithContext(path) { const [pathname, search = ""] = path.split("?"); const route = routeFor(pathname); const params = new URLSearchParams(search); return { ...route, chapter: params.get("chapter") || "", knowledge: params.get("knowledge") || "", practiceType: params.get("type") || "" }; }
function Icon({ name }) { return <span className={`mobile-icon mobile-icon-${name}`} aria-hidden="true">{icons[name] || "•"}</span>; }

function useResource(loader, dependencies) { const requestKey = JSON.stringify(dependencies); const [state, setState] = useState({ status: "loading", data: null, error: "", requestKey }); const [revision, setRevision] = useState(0); useEffect(() => { let active = true; setState({ status: "loading", data: null, error: "", requestKey }); loader().then((data) => active && setState({ status: "success", data, error: "", requestKey })).catch((error) => active && setState({ status: "error", data: null, error: error.message || "暂时无法读取数据", requestKey })); return () => { active = false; }; }, [...dependencies, revision]); return { ...state, status: state.requestKey === requestKey ? state.status : "loading", data: state.requestKey === requestKey ? state.data : null, error: state.requestKey === requestKey ? state.error : "", requestKey, retry: () => setRevision((value) => value + 1) }; }
async function getJson(path, options = {}) { const response = await fetch(`${API_BASE}${path}`, { credentials: "include", ...options }); const data = await response.json().catch(() => ({})); if (!response.ok) { const detail = typeof data.detail === "string" ? data.detail : data.detail?.message || data.detail?.error || ""; throw new Error(detail || `请求失败（${response.status}）`); } return data; }

function MobileAuth({ onAuthenticated }) { const [mode, setMode] = useState("login"); const [username, setUsername] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const submit = async (event) => { event.preventDefault(); setBusy(true); setError(""); try { const response = await fetch(`${API_BASE}/${mode === "login" ? "login" : "register"}`, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify({ username: username.trim(), password }) }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "账号或密码不正确"); const meResponse = await fetch(`${API_BASE}/me`, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify({ username: username.trim() }) }); const me = await meResponse.json(); const user = me.user || data.user || data.profile; if (!user) throw new Error("认证成功但未返回用户信息"); localStorage.setItem("ai_study_platform_user", JSON.stringify(user)); onAuthenticated(user); } catch (reason) { setError(reason.message || "暂时无法登录"); } finally { setBusy(false); } }; return <main className="mobile-auth"><div className="auth-mark">AI</div><h1>把学习带在身边</h1><p>课程学习与 11408 考研，分开管理。</p><form onSubmit={submit}><label>账号<input value={username} onChange={(event) => setUsername(event.target.value)} placeholder="输入账号" required /></label><label>密码<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="输入密码" required /></label>{error && <div className="auth-error" role="alert">{error}</div>}<button className="primary-button" type="submit" disabled={busy}>{busy ? "处理中…" : mode === "login" ? "进入学习" : "注册并开始"}</button></form><button className="auth-toggle" onClick={() => { setMode(mode === "login" ? "register" : "login"); setError(""); }}>{mode === "login" ? "还没有账号？注册" : "已有账号？登录"}</button></main>; }

function coursePath(mode, id, suffix = "") { return `/m/course/${mode}/${encodeURIComponent(id)}${suffix}`; }
function AppShell({ route, user, contextLabel, children }) { const context = route.space === COURSE ? route.courseId : route.subject; const chatMode = route.page === "ai" || route.page === "exam-ai"; const tabs = context && !chatMode ? (route.space === EXAM ? [["home", "首页", `/m/exam11408/${context}/home`], ["knowledge", "章节", `/m/exam11408/${context}/chapters`], ["practice", "练习", `/m/exam11408/${context}/practice`], ["ai", "AI", `/m/exam11408/${context}/ai`], ["profile", "我的", "/m/profile"]] : [["home", "首页", coursePath(route.mode || "daily", context, "/home")], ["knowledge", "知识点", coursePath(route.mode || "daily", context, "/knowledge")], ["ai", "AI", coursePath(route.mode || "daily", context, "/ai")], ["practice", "练习", coursePath(route.mode || "daily", context, "/practice")], ["profile", "我的", "/m/profile"]]) : []; const active = ["course-home", "exam-home"].includes(route.page) ? "home" : route.page === "course-knowledge" || route.page === "exam-chapters" ? "knowledge" : route.page === "ai" || route.page === "exam-ai" ? "ai" : route.page === "course-practice" || route.page === "exam-practice" ? "practice" : route.page.replace("course-", "").replace("exam-", ""); const secondary = Boolean(route.courseId || route.subject || route.page.startsWith("profile-")); const parentPath = route.page.startsWith("profile-") ? "/m/profile" : route.courseId ? coursePath(route.mode || "daily", route.courseId, "/home") : route.subject ? `/m/exam11408/${route.subject}/home` : "/m"; return <div className={`mobile-app${chatMode ? " is-chat" : ""}`}>{!chatMode && <header className="mobile-header"><button className="brand-button" onClick={() => go(route.space === EXAM ? "/m/exam11408" : "/m/course")}><span className="brand-mark">AI</span><span>Study</span></button>{contextLabel && <div className="header-context">{contextLabel}</div>}{secondary ? <button className="header-back" onClick={() => goBack(parentPath)} aria-label="返回上一级">‹ 返回</button> : <button className="header-avatar" onClick={() => go("/m/profile")} aria-label="打开我的">{(user.nickname || user.username || "学").slice(0, 1)}</button>}</header>}<main className={`mobile-content${chatMode ? " mobile-chat-content" : ""}`}>{children}</main>{tabs.length > 0 && <nav className="bottom-nav" aria-label="移动端主导航">{tabs.map(([key, label, path]) => <button key={key} className={active === key ? "is-active" : ""} onClick={() => go(path)}><Icon name={key} /><span>{label}</span></button>)}</nav>}</div>; }
function PageHeading({ eyebrow, title, description }) { return <div className="page-heading">{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description && <p>{description}</p>}</div>; }
function SectionTitle({ title }) { return <div className="section-title"><h2>{title}</h2></div>; }
function ActionRow({ icon, title, description, onClick }) { return <button className="action-row" onClick={onClick}><Icon name={icon} /><span><strong>{title}</strong>{description && <small>{description}</small>}</span><b>›</b></button>; }
function AsyncState({ state, emptyTitle, emptyDescription }) { if (state.status === "loading") return <div className="inline-state">正在读取 PC 端数据…</div>; if (state.status === "error") return <div className="inline-error">{state.error}<button className="text-button" onClick={state.retry}>重试</button></div>; if (state.status === "empty" || (state.status === "success" && !state.data && emptyTitle)) return <div className="empty-course"><strong>{emptyTitle}</strong><span>{emptyDescription}</span></div>; return null; }
const KNOWLEDGE_STATUS = [["not_started", "未学习"], ["learning", "学习中"], ["mastered", "已学习"], ["review_due", "待复习"]];
function knowledgeTitle(node) { return node?.title || node?.name || "未命名知识点"; }
function knowledgeStatusLabel(status) { return KNOWLEDGE_STATUS.find(([value]) => value === status)?.[1] || "未学习"; }
function taskStatusLabel(status) { return ({ done: "已完成", completed: "已完成", in_progress: "进行中", doing: "进行中", pending: "待开始", todo: "待开始" })[status] || "待开始"; }
function attemptCorrect(result) { return result?.is_correct ?? result?.correct; }
function knowledgeLeaves(nodes, chapter = "", result = []) { (nodes || []).forEach((node) => { const nextChapter = chapter || node.title || node.name || ""; if ((node.children || []).length) knowledgeLeaves(node.children, nextChapter, result); else result.push({ ...node, chapter: nextChapter }); }); return result; }
function knowledgeCourseId(course) { return courseId(course); }
function MobileKnowledgeNode({ node, onSelect, depth = 0 }) { const [expanded, setExpanded] = useState(false); const children = safeArray(node.children); return <div className={`mobile-knowledge-node depth-${Math.min(depth, 3)}${expanded ? " is-expanded" : " is-collapsed"}`}><button type="button" className="mobile-knowledge-node-row" onClick={() => onSelect(node)}><span className="mobile-knowledge-toggle" onClick={(event) => { if (!children.length) return; event.stopPropagation(); setExpanded((value) => !value); }}>{children.length ? (expanded ? "⌄" : "›") : "•"}</span><span><strong>{knowledgeTitle(node)}</strong><small>{children.length ? `${children.length} 个子节点` : knowledgeStatusLabel(node.status)}</small></span><b>›</b></button>{expanded && children.length > 0 && <div className="mobile-knowledge-node-children">{children.map((child) => <MobileKnowledgeNode key={child.id || child.code || child.title} node={child} onSelect={onSelect} depth={depth + 1} />)}</div>}</div>; }

function CourseModeSelect() { return <div className="page"><PageHeading title="课程学习" description="先选择学习模式，再进入 PC 端同步的课程数据。" /><SectionTitle title="选择学习模式" /><div className="mode-select-list"><button className="mode-select-card mode-daily" onClick={() => go("/m/course/daily")}><span className="mode-icon"><Icon name="book" /></span><span><strong>平日学习</strong><small>学习用户已经添加的课程</small><b>查看我的课程 ›</b></span></button><button className="mode-select-card mode-exam" onClick={() => go("/m/course/exam")}><span className="mode-icon"><Icon name="exam" /></span><span><strong>考前突击</strong><small>查看 PC 端已有的考试任务</small><b>进入课程冲刺 ›</b></span></button></div></div>; }
function CourseDaily({ user }) { const state = useResource(() => getJson(`/course-learning/courses?username=${encodeURIComponent(user.username)}`), [user.username]); const courses = safeArray(state.data?.courses).filter((course) => courseLearningMode(course) === "daily"); return <div className="page"><PageHeading eyebrow="课程学习" title="平日学习" description="与 PC Web 使用同一用户课程集合，当前页仅展示平日学习课程。" />{state.status === "success" && courses.length === 0 ? <div className="empty-course"><strong>暂无平日学习课程</strong><span>当前用户课程集合中没有 primary_mode 为平日学习的课程。</span></div> : state.status === "success" ? <div className="selection-list">{courses.map((course) => <button className="selection-card course-selection" key={courseId(course)} onClick={() => go(coursePath("daily", courseId(course), "/home"))}><span className="selection-icon"><Icon name="book" /></span><span><strong>{courseName(course)}</strong><small>{courseLearningModeLabel(course)} · {course.material_count || 0} 份资料 · {course.pending_task_count || 0} 个计划</small></span><b>›</b></button>)}</div> : <AsyncState state={state} emptyTitle="暂无课程" emptyDescription="请在电脑端添加课程，手机端自动同步。" />}</div>; }
function CourseExam({ user }) { const state = useResource(() => getJson(`/course-learning/courses?username=${encodeURIComponent(user.username)}`), [user.username]); const courses = safeArray(state.data?.courses).filter((course) => courseLearningMode(course) === "exam"); return <div className="page"><PageHeading eyebrow="课程学习" title="考前突击" description="与 PC Web 使用同一用户课程集合，当前页仅展示 primary_mode 为考前突击的课程。" />{state.status === "success" && courses.length === 0 ? <div className="empty-course"><strong>暂无考前突击课程</strong><span>当前用户课程集合中没有设置为考前突击的课程。</span></div> : state.status === "success" ? <div className="task-list">{courses.map((course) => <button className="task-card" key={courseId(course)} onClick={() => go(coursePath("exam", courseId(course), "/home"))}><span className="task-mark"><Icon name="exam" /></span><span><strong>{courseName(course)}</strong><small>{courseLearningModeLabel(course)} · {course.material_count || 0} 份资料 · {course.pending_task_count || 0} 个计划</small></span><b>›</b></button>)}</div> : <AsyncState state={state} emptyTitle="暂无课程" emptyDescription="课程列表读取失败，请点击重试。" />}</div>; }
function ContextBar({ mode, name, onChange }) { return <button className="context-bar" onClick={onChange}><span>{MODE_LABELS[mode]}</span><strong>{name}</strong><b>切换 ›</b></button>; }
function CourseHome({ course, mode, user }) {
  const id = courseId(course);
  const name = courseName(course);
  const detail = useResource(() => mode === "exam"
    ? Promise.all([
      getJson(`/course-learning/exam-settings?username=${encodeURIComponent(user.username)}&course_id=${encodeURIComponent(id)}`),
      getJson(`/course-learning/today-plan?username=${encodeURIComponent(user.username)}`),
    ]).then(([settings, plan]) => ({ settings: settings.settings || {}, today: safeArray(plan.items).filter((item) => String(item.course_id) === id) }))
    : Promise.resolve(null), [mode, id, user.username]);
  const examSettings = detail.data?.settings || {};
  return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[mode]}`} title="首页" description="当前课程的学习入口。" /><ContextBar mode={mode} name={name} onChange={() => go("/m/course")} /><section className="hero-card course-hero"><div><span className="card-label">当前课程</span><h2>{name}</h2><p>{MODE_LABELS[mode]} · 课程数据与 PC Web 同步。</p></div><div className="hero-orb"><Icon name="book" /></div></section>{mode === "exam" && <section className="course-mode-detail"><SectionTitle title="考前突击信息" />{detail.status === "loading" ? <div className="inline-state">正在读取考试信息…</div> : detail.status === "error" ? <AsyncState state={detail} emptyTitle="考试信息读取失败" emptyDescription="请稍后重试。" /> : <div className="exam-info-grid"><div><span>考试日期</span><strong>{examSettings.exam_date || "暂未设置考试日期"}</strong></div><div><span>考试目标</span><strong>{examSettings.target || "暂未设置考试目标"}</strong></div><div><span>今日任务</span><strong>{detail.data?.today?.length ? `${detail.data.today.length} 项` : "暂无今日复习任务"}</strong></div></div>}</section>}<SectionTitle title="学习入口" /><div className="course-entry-grid"><button onClick={() => go(coursePath(mode, id, "/knowledge"))}><Icon name="knowledge" /><strong>知识点</strong><small>查看知识图谱</small></button><button onClick={() => go(coursePath(mode, id, "/practice"))}><Icon name="practice" /><strong>章节练习</strong><small>巩固当前内容</small></button><button onClick={() => go(coursePath(mode, id, "/plan"))}><Icon name="book" /><strong>学习计划</strong><small>查看当前任务</small></button><button onClick={() => go(coursePath(mode, id, "/ai"))}><Icon name="ai" /><strong>AI助手</strong><small>当前课程上下文</small></button></div></div>;
}

function CoursePlan({ user, course, mode }) { const id = courseId(course); const name = courseName(course); const state = useResource(() => getJson(`/course-learning/study-plan?username=${encodeURIComponent(user.username)}&course_id=${encodeURIComponent(id)}`), [user.username, id]); const tasks = safeArray(state.data?.tasks || state.data?.items); return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[mode]}`} title="学习计划" description={`${name} · 计划数据来自 PC Web。`} />{state.status === "success" && tasks.length === 0 ? <div className="empty-course"><strong>暂无学习计划</strong><span>请在电脑端课程学习系统中创建计划，手机端自动同步。</span></div> : state.status === "success" ? <div className="task-list">{tasks.map((task) => <ActionRow key={task.id} icon="book" title={task.title || "学习任务"} description={`${taskStatusLabel(task.status)} · ${name}`} onClick={() => {}} />)}</div> : <AsyncState state={state} emptyTitle="暂无学习计划" emptyDescription="请在电脑端课程学习系统中创建计划，手机端自动同步。" />}</div>; }

function CourseExamTask({ user, course, route }) { const id = courseId(course); const name = courseName(course); const state = useResource(async () => { const [plan, studyPlan] = await Promise.all([getJson(`/course-learning/today-plan?username=${encodeURIComponent(user.username)}`), getJson(`/course-learning/study-plan?username=${encodeURIComponent(user.username)}&course_id=${encodeURIComponent(id)}`)]); return { task: safeArray(plan.items).find((item) => String(item.id) === String(route.taskId) && item.mode === "exam"), chapters: safeArray(studyPlan.chapters) }; }, [user.username, id, route.taskId]); const task = state.data?.task; const chapters = state.data?.chapters || []; return <div className="page"><PageHeading eyebrow="课程学习 · 考前突击" title="考试任务" description="独立的课程考前突击上下文。" />{state.status === "success" && <><section className="exam-task-summary"><span>考试课程</span><strong>{name}</strong><small>{task?.title || "当前考试任务"}</small></section><SectionTitle title="复习计划" /><div className="task-detail-panel"><strong>{task?.title || "复习计划"}</strong><p>计划状态：{task?.status || "未完成"}</p><p>截止时间：{task?.due_date || "未设置"}</p></div><SectionTitle title="重点章节" /><div className="task-detail-list">{chapters.slice(0, 4).map((chapter) => <div key={chapter.code || chapter.title} className="task-detail-row"><Icon name="book" /><span>{chapter.title || chapter.name || "重点章节"}</span></div>)}{chapters.length === 0 && <div className="task-detail-panel"><p>重点章节由 PC 端学习计划提供。</p></div>}</div><div className="course-task-actions"><button className="primary-button" onClick={() => go(coursePath("exam", id, "/practice"))}>进入练习</button><button className="secondary-button" onClick={() => go(coursePath("exam", id, "/ai"))}>AI助手</button></div></>}{state.status !== "success" && <AsyncState state={state} emptyTitle="暂无考试任务" emptyDescription="请在电脑端课程学习系统中配置考前突击任务。" />}</div>; }
function MobileKnowledgeChapter({ chapter, onSelect }) { const [expanded, setExpanded] = useState(false); const title = chapter.title || chapter.name; const points = knowledgeLeaves(chapter.children || [], title); return <section className={`mobile-knowledge-chapter${expanded ? " is-expanded" : " is-collapsed"}`}><button type="button" className="mobile-knowledge-chapter-head" onClick={() => setExpanded((value) => !value)}><span className="mobile-knowledge-toggle">{expanded ? "⌄" : "›"}</span><strong>{title}</strong><span>{points.length} 个知识点</span></button>{expanded && <div className="mobile-knowledge-points">{safeArray(chapter.children).map((node) => <MobileKnowledgeNode key={node.id || node.code || node.title} node={node} onSelect={onSelect} />)}</div>}</section>; }

function CourseKnowledge({ user, course, mode }) {
  const id = knowledgeCourseId(course);
  const name = courseName(course);
  const state = useResource(() => getJson(`/knowledge-map?course_id=${encodeURIComponent(id)}&username=${encodeURIComponent(user.username)}`), [id, user.username]);
  const chapters = safeArray(state.data?.chapters);
  const [selected, setSelected] = useState(null);
  const [saving, setSaving] = useState("");
  const [notice, setNotice] = useState("");
  const saveStatus = async (status) => {
    if (!selected?.code || selected.children?.length || !user.username) return;
    setSaving(status);
    setNotice("");
    try {
      const response = await fetch(`${API_BASE}/knowledge-map/progress`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, course_id: id, knowledge_point_code: selected.code, knowledge_point_title: knowledgeTitle(selected), status }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || "掌握程度保存失败");
      setSelected((previous) => ({ ...previous, status: data.node?.status || status }));
      setNotice("掌握程度已保存");
    } catch (error) { setNotice(error.message || "掌握程度保存失败"); }
    finally { setSaving(""); }
  };
  if (state.status !== "success") return <div className="page"><PageHeading eyebrow={`课程 · ${name} · ${MODE_LABELS[mode]}`} title="知识点" description="课程知识图谱与 PC Web 同步。" /><AsyncState state={state} emptyTitle="暂无知识图谱" emptyDescription="PC 端还没有为这门课程生成知识图谱。" /></div>;
  if (!chapters.length) return <div className="page"><PageHeading eyebrow={`课程 · ${name} · ${MODE_LABELS[mode]}`} title="知识点" description="课程知识图谱与 PC Web 同步。" /><div className="empty-course"><strong>暂无知识图谱</strong><span>PC 端还没有为这门课程生成知识图谱。</span></div></div>;
  const aiPath = `${coursePath(mode, id, "/ai")}?chapter=${encodeURIComponent(selected?.chapter || "")}&knowledge=${encodeURIComponent(knowledgeTitle(selected))}`; const practicePath = `${coursePath(mode, id, "/practice")}?chapter=${encodeURIComponent(selected?.chapter || "")}&knowledge=${encodeURIComponent(knowledgeTitle(selected))}`;
  return <div className="page"><PageHeading eyebrow={`课程 · ${name} · ${MODE_LABELS[mode]}`} title="知识点" description="课程知识图谱与 PC Web 同步。" /><section className="map-card"><div className="map-title"><Icon name="knowledge" /><span><strong>{name}知识图谱</strong><small>章节、小节和知识点默认折叠，点击逐级展开</small></span></div></section><div className="mobile-knowledge-chapters">{chapters.map((chapter) => <MobileKnowledgeChapter key={chapter.code || chapter.id || chapter.title} chapter={chapter} onSelect={(node) => { setSelected(node); setNotice(""); }} />)}</div>{selected ? <div className="sheet-backdrop" role="presentation" onClick={() => setSelected(null)}><section className="bottom-sheet" role="dialog" aria-modal="true" aria-label="知识点详情" onClick={(event) => event.stopPropagation()}><div className="sheet-handle" /><div className="sheet-header"><h2>{knowledgeTitle(selected)}</h2><button type="button" aria-label="关闭" onClick={() => setSelected(null)}>×</button></div><div className="mastery-panel"><span>掌握程度</span><div className="mastery-options">{KNOWLEDGE_STATUS.map(([value, label]) => <button key={value} type="button" className={selected.status === value ? "is-active" : ""} disabled={saving !== "" || Boolean(selected.children?.length)} onClick={() => saveStatus(value)}>{saving === value ? "保存中…" : label}</button>)}</div></div>{notice && <div className="sheet-notice">{notice}</div>}<div className="sheet-actions"><button type="button" className="secondary-button" onClick={() => go(aiPath)}>AI解释</button><button type="button" className="primary-button" onClick={() => go(practicePath)}>进入练习</button></div></section></div> : null}</div>;
}
function ExamKnowledgeSheet({ subject, selected, onClose, onSaved }) { const [status, setStatus] = useState(selected?.status || "not_started"); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState(""); useEffect(() => { setStatus(selected?.status || "not_started"); setNotice(""); }, [selected]); if (!selected) return null; const title = knowledgeTitle(selected); const save = async (next) => { setSaving(true); setNotice(""); try { const user = readUser(); const response = await fetch(`${API_BASE}/knowledge-map/progress`, { method: "PATCH", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify({ username: user.username, course_id: examMapCourseId(subject), knowledge_point_code: selected.code || selected.id || title, knowledge_point_title: title, status: next }) }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "保存失败"); setStatus(next); setNotice("已保存，11408状态与课程学习独立。"); onSaved?.(selected, next, data); } catch (error) { setNotice(error.message || "保存失败"); } finally { setSaving(false); } }; return <div className="mobile-sheet-backdrop" role="presentation" onClick={onClose}><section className="mobile-bottom-sheet" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="sheet-handle" /><div className="sheet-heading"><div><span className="eyebrow">11408知识点</span><h2>{title}</h2></div><button className="sheet-close" onClick={onClose} aria-label="关闭">×</button></div><div className="mastery-panel"><span>掌握程度</span><div className="mastery-options">{KNOWLEDGE_STATUS.map(([value, label]) => <button key={value} type="button" className={status === value ? "is-active" : ""} disabled={saving} onClick={() => save(value)}>{saving && status !== value ? "" : label}</button>)}</div></div>{notice && <div className="sheet-notice">{notice}</div>}<div className="sheet-actions"><button className="secondary-button" onClick={() => go(`/m/exam11408/${subject}/ai?chapter=${encodeURIComponent(selected.chapter || "")}&knowledge=${encodeURIComponent(title)}`)}>AI解释</button><button className="primary-button" onClick={() => go(`/m/exam11408/${subject}/practice?type=past-paper&chapter=${encodeURIComponent(selected.chapter || "")}&knowledge=${encodeURIComponent(title)}`)}>进入练习</button></div></section></div>; }

function ExamChaptersMobile({ user, subject, chapter }) { const name = EXAM_SUBJECTS.find(([id]) => id === subject)?.[1] || subject; const state = useResource(() => getJson(`/knowledge-map?course_id=${encodeURIComponent(examMapCourseId(subject))}&username=${encodeURIComponent(user.username)}`), [subject, user.username]); const [selected, setSelected] = useState(null); const [statuses, setStatuses] = useState({}); const chapters = safeArray(state.data?.chapters); const select = (node, parent = "") => setSelected({ ...node, chapter: parent || chapter || node.chapter || "" }); const renderNode = (node, depth = 0, parent = "") => { const children = safeArray(node.children); const title = knowledgeTitle(node); const current = statuses[node.code || node.id] || node.status; return <div className={`mobile-knowledge-node depth-${Math.min(depth, 3)}${children.length ? " is-collapsed" : ""}`} key={node.code || node.id || title}><button type="button" className="mobile-knowledge-node-row" onClick={() => select({ ...node, status: current }, parent)}><span className="mobile-knowledge-toggle" onClick={(event) => { if (!children.length) return; event.stopPropagation(); event.currentTarget.parentElement?.parentElement?.classList.toggle("is-collapsed"); }}>{children.length ? "›" : "•"}</span><span><strong>{title}</strong><small>{children.length ? `${children.length} 个子节点` : knowledgeStatusLabel(current)}</small></span><b>›</b></button>{children.length > 0 && <div className="mobile-knowledge-node-children">{children.map((child) => renderNode(child, depth + 1, parent || title))}</div>}</div>; }; return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="章节" description="章节与知识点来自 PC 端知识图谱。" />{state.status !== "success" ? <AsyncState state={state} emptyTitle="暂无章节数据" emptyDescription="PC 端还没有为该科目生成章节结构。" /> : chapters.length === 0 ? <div className="empty-course"><strong>暂无章节数据</strong><span>PC 端还没有为该科目生成章节结构。</span></div> : <><section className="chapter-context-card"><Icon name="book" /><div><strong>{chapter || "选择章节"}</strong><small>科目：{name}</small></div></section><div className="mobile-exam-tree">{chapters.map((node) => renderNode(node))}</div><div className="chapter-action-row"><button className="secondary-button" onClick={() => go(`/m/exam11408/${subject}/practice?chapter=${encodeURIComponent(chapter || "")}`)}>进入练习</button><button className="primary-button" onClick={() => go(`/m/exam11408/${subject}/ai?chapter=${encodeURIComponent(chapter || "")}`)}>进入 AI助手</button></div></>}{selected && <ExamKnowledgeSheet subject={subject} selected={selected} onClose={() => setSelected(null)} onSaved={(node, next) => setStatuses((previous) => ({ ...previous, [node.code || node.id]: next }))} />}</div>; }

function MobileQuestion({ question, answer, onAnswer, disabled }) { if (!question) return null; const options = questionOptions(question); return <div className="mobile-practice-question"><div className="mobile-question-meta">{question.year ? `${question.year} 年 · ` : ""}{question.question_type || question.type || "选择题"}</div><h2>{question.stem || question.title || question.content || ""}</h2>{options.length ? <div className="mobile-question-options">{options.map(([key, value]) => <button type="button" key={key} className={answer === key ? "is-selected" : ""} disabled={disabled} onClick={() => onAnswer(key)}><strong>{key}</strong><span>{value}</span></button>)}</div> : <textarea className="mobile-answer-input" value={answer || ""} onChange={(event) => onAnswer(event.target.value)} placeholder="输入答案" disabled={disabled} />}</div>; }

function ExamPracticeMobile({ route, user }) { const subject = route.subject; const name = EXAM_SUBJECTS.find(([id]) => id === subject)?.[1] || subject; const type = route.practiceType || ""; const [data, setData] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [year, setYear] = useState(""); const [attemptId, setAttemptId] = useState(""); const [questions, setQuestions] = useState([]); const [answers, setAnswers] = useState({}); const [result, setResult] = useState(null); const [selectedWrong, setSelectedWrong] = useState(null); const [wrongAnswer, setWrongAnswer] = useState(""); const [busy, setBusy] = useState(false); useEffect(() => { setData(null); setQuestions([]); setAttemptId(""); setResult(null); setError(""); if (!type) { setLoading(false); return; } setLoading(true); const path = type === "past-paper" ? `/exam/11408/${subject}/past-papers` : type === "wrong" ? `/exam/11408/${subject}/wrong-questions?username=${encodeURIComponent(user.username)}` : `/exam/11408/${subject}/ai-questions?username=${encodeURIComponent(user.username)}`; getJson(path).then(setData).catch((e) => setError(e.message || "读取练习数据失败")).finally(() => setLoading(false)); }, [subject, type, user.username]); const startPast = async () => { if (!year) return setError("请先选择年份"); setBusy(true); setError(""); try { const started = await getJson(`/exam/11408/${subject}/past-paper-attempts`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, year: Number(year) }) }); await loadAttempt(started.attempt_id || started.id); } catch (e) { setError(e.message); } finally { setBusy(false); } }; const loadAttempt = async (id, ai = false) => { setAttemptId(id); const detail = await getJson(`/exam/11408/${subject}/${ai ? "ai-questions/attempts" : "past-paper-attempts"}/${id}${ai ? `?username=${encodeURIComponent(user.username)}` : ""}`); setQuestions(safeArray(detail.questions)); setAnswers(detail.saved_answers || {}); setResult(null); }; const startAi = async () => { const items = safeArray(data?.items); if (!items.length) return setError("暂无 AI出题"); setBusy(true); try { const started = await getJson(`/exam/11408/${subject}/ai-questions/attempts`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, question_ids: items.map((item) => item.id), knowledge_point_path: route.chapter || "" }) }); await loadAttempt(started.attempt_id || started.id, true); } catch (e) { setError(e.message); } finally { setBusy(false); } }; const submitAttempt = async (ai = false) => { if (!attemptId) return; setBusy(true); try { const path = `/exam/11408/${subject}/${ai ? "ai-questions/attempts" : "past-paper-attempts"}/${attemptId}/submit`; const payload = ai ? { username: user.username, answers } : { username: user.username, answers: questions.map((question) => ({ question_id: question.id, user_answer: String(answers[question.id] || "") })) }; setResult(await getJson(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) })); } catch (e) { setError(e.message); } finally { setBusy(false); } }; const finishWrong = async () => { if (!selectedWrong) return; setBusy(true); try { await getJson(`/exam/11408/${subject}/wrong-questions/${selectedWrong.id}/mastered`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username }) }); setSelectedWrong(null); setWrongAnswer(""); setData((previous) => ({ ...previous, items: safeArray(previous?.items).filter((item) => item.id !== selectedWrong.id) })); } catch (e) { setError(e.message); } finally { setBusy(false); } }; const entries = [{ type: "past-paper", title: "真题练习", icon: "practice" }, { type: "wrong", title: "错题练习", icon: "knowledge" }, { type: "ai", title: "AI出题", icon: "ai" }]; if (!type) return <div className="page"><PageHeading eyebrow="11408考研中心" title="练习" description={`${name} · 真实练习入口`} /><div className="practice-list">{entries.map((entry) => <ActionRow key={entry.type} icon={entry.icon} title={entry.title} description="进入当前科目的真实数据" onClick={() => go(`/m/exam11408/${subject}/practice?type=${entry.type}${route.chapter ? `&chapter=${encodeURIComponent(route.chapter)}` : ""}`)} />)}</div></div>; if (loading) return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title={type === "ai" ? "AI出题" : type === "wrong" ? "错题练习" : "真题练习"} /><div className="inline-state">正在读取 PC 端数据…</div></div>; const items = safeArray(data?.items); const years = safeArray(data?.years).filter((item) => Number.isFinite(Number(item))); if (type === "past-paper" && !attemptId) return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="真题练习" description="选择年份后开始答题。" />{error && <div className="inline-error">{error}</div>}<div className="year-list">{years.map((item) => <button key={item} className={year === String(item) ? "is-active" : ""} onClick={() => setYear(String(item))}>{item} 年真题</button>)}</div><button className="primary-button" disabled={busy || !year} onClick={startPast}>{busy ? "准备中…" : "开始答题"}</button></div>; if (type === "wrong" && !selectedWrong) return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="错题练习" description="重新练习当前错题，完成后沿用 PC 错题状态。" />{error && <div className="inline-error">{error}</div>}{items.length ? <div className="wrong-list">{items.map((item) => <button key={item.id} className="wrong-card" onClick={() => setSelectedWrong(item)}><strong>{item.stem || item.question_title || "错题"}</strong><small>{item.year ? `${item.year} 年` : ""} · {item.knowledge_point_name || "当前科目"}</small></button>)}</div> : <div className="empty-course"><strong>暂无错题</strong><span>PC 端当前没有待重新练习的错题。</span></div>}</div>; if (type === "wrong" && selectedWrong) return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="重新练习" description="完成后同步 PC 错题掌握状态。" /><MobileQuestion question={selectedWrong} answer={wrongAnswer} onAnswer={setWrongAnswer} disabled={busy} />{selectedWrong.analysis && <div className="mobile-practice-result"><strong>解析</strong><p>{selectedWrong.analysis}</p></div>}<button className="primary-button" disabled={!wrongAnswer || busy} onClick={finishWrong}>{busy ? "保存中…" : "完成重练"}</button></div>; if (type === "ai" && !attemptId) return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="AI出题" description="使用 PC 端已有 AI 题目开始练习。" />{error && <div className="inline-error">{error}</div>}{items.length ? <><div className="practice-data-panel">{items.slice(0, 12).map((item, index) => <div className="practice-data-row" key={item.id || index}><span>{index + 1}</span><strong>{item.stem || item.title || "AI题目"}</strong></div>)}</div><button className="primary-button" disabled={busy} onClick={startAi}>{busy ? "准备中…" : "开始 AI出题练习"}</button></> : <div className="empty-course"><strong>暂无 AI出题</strong><span>PC 端当前没有可练习的 AI 题目。</span></div>}</div>; const ai = type === "ai"; return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title={ai ? "AI出题" : "真题练习"} description={`${route.chapter || "当前科目"} · 答题与解析来自 PC 接口`} />{error && <div className="inline-error">{error}</div>}{result ? <div className="mobile-result-panel"><strong>提交完成</strong><span>结果由 PC 端接口返回</span>{safeArray(result.results).map((item, index) => <article key={item.question_id || index}><h3>第 {index + 1} 题 · {item.correct ? "正确" : "错误"}</h3><p>你的答案：{item.user_answer || "未作答"}</p><p>标准答案：{item.standard_answer || "暂无"}</p>{item.analysis && <p>解析：{item.analysis}</p>}</article>)}</div> : <>{questions.map((question, index) => <div key={question.id || index}><MobileQuestion question={question} answer={answers[question.id] || ""} onAnswer={(value) => setAnswers((previous) => ({ ...previous, [question.id]: value }))} disabled={false} /><div className="mobile-question-index">第 {index + 1} / {questions.length} 题</div></div>)}<button className="primary-button" disabled={busy || !questions.length} onClick={() => submitAttempt(ai)}>{busy ? "提交中…" : "提交答案"}</button></>}</div>; }

function AIHome({ route, course }) { const name = course ? courseName(course) : route.space === EXAM ? (EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject) : ""; const label = course ? `课程 AI助手 · ${name}` : route.space === EXAM ? `11408 AI助手 · ${name}` : "AI助手"; const chapterLabel = route.chapter || "未选择章节"; return <div className="page"><PageHeading eyebrow={course ? `课程学习 · ${MODE_LABELS[route.mode]}` : route.space === EXAM ? "11408考研中心" : "独立服务"} title="AI助手" description={`${label} · 上下文自动携带`} /><section className="ai-empty"><div className="ai-icon"><Icon name="ai" /></div><h2>{label}</h2><div className="ai-context-row"><span>{course ? "courseId" : "examSubject"}</span><strong>{course ? course.course_id || course.id : route.subject}</strong></div><div className="ai-context-row"><span>chapter</span><strong>{chapterLabel}</strong></div>{(course || route.space === EXAM) && <div className="ai-context-row"><span>knowledge</span><strong>{route.knowledge || "未选择知识点"}</strong></div>}<p>历史对话按当前学习空间自动隔离，不提供手动模式选择。</p><button className="primary-button" onClick={() => go("/m/profile")}>查看我的空间</button></section></div>; }
function MobileAIChat({ route, course, user }) {
  const exam = route.space === EXAM;
  const courseLabel = course ? courseName(course) : "普通 AI";
  const subjectLabel = exam ? (EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject) : courseLabel;
  const context = exam
    ? { space: "11408", subject: route.subject, chapter: route.chapter, knowledge: route.knowledge }
    : course
      ? { space: "course", courseId: courseId(course), courseName: courseLabel, learningMode: route.mode, chapterId: route.chapterId || route.chapter, knowledgeId: route.knowledgeId || route.knowledge, chapter: route.chapter, knowledge: route.knowledge }
      : { space: "general" };
  const [sessions, setSessions] = useState([]); const [sessionId, setSessionId] = useState(null); const [messages, setMessages] = useState([]); const [input, setInput] = useState(""); const [loading, setLoading] = useState(false); const [loadingHistory, setLoadingHistory] = useState(true); const [error, setError] = useState(""); const [menu, setMenu] = useState(null); const [editingId, setEditingId] = useState(""); const [editingText, setEditingText] = useState(""); const [uploading, setUploading] = useState(false); const inputRef = useRef(null); const fileRef = useRef(null); const messagesRef = useRef(null);
  const scopeQuery = () => { const query = new URLSearchParams({ username: user.username }); if (exam) { query.set("subject_key", route.subject); query.set("exam_subject", route.subject); query.set("subject", subjectLabel); } else if (course) { query.set("course", courseLabel); query.set("course_id", courseId(course)); query.set("subject", courseLabel); } return query; };
  const chatContext = { ...context, courseId: context.courseId || undefined, chapterId: context.chapterId || undefined, knowledgeId: context.knowledgeId || undefined };
  const loadHistory = async () => { setLoadingHistory(true); try { const response = await fetch(`${API_BASE}/chat/history?${scopeQuery()}`); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "历史对话加载失败"); setSessions(safeArray(data.sessions)); } catch (reason) { setSessions([]); setError(reason.message || "历史对话加载失败"); } finally { setLoadingHistory(false); } };
  const loadSession = async (id) => { try { const response = await fetch(`${API_BASE}/chat/sessions/${id}?${scopeQuery()}`); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "打开对话失败"); setSessionId(data.session?.id || id); setMessages(safeArray(data.messages).map((item) => ({ ...item, id: item.id || `${item.role}-${Date.now()}-${Math.random()}` }))); setMenu(null); } catch (reason) { setError(reason.message || "打开对话失败"); } };
  useEffect(() => { setSessionId(null); setMessages([]); setInput(""); setError(""); loadHistory(); }, [route.space, route.subject, route.courseId, route.mode, route.chapter, route.knowledge, user.username]);
  useEffect(() => { const node = messagesRef.current; if (node) node.scrollTop = node.scrollHeight; }, [messages, loading]);
  const send = async (text = input, options = {}) => { const message = String(text || "").trim(); if (!message || loading) return; setLoading(true); setError(""); setInput(""); const localId = `mobile-user-${Date.now()}`; setMessages((prev) => [...prev, { id: localId, role: "user", content: message, created_at: new Date().toISOString() }]); try { const payload = { username: user.username, message, subject: exam ? subjectLabel : courseLabel, course: courseLabel, session_id: sessionId, branch_id: options.branchId || "", edit_source_message_id: options.sourceId ? Number(options.sourceId) || null : undefined, knowledge_context: chatContext }; if (exam) Object.assign(payload, { subject_key: route.subject, exam_subject: route.subject }); const response = await fetch(`${API_BASE}/chat`, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify(payload) }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "AI 服务调用失败"); const nextSession = data.session?.id || data.session_id || sessionId; setSessionId(nextSession || null); setMessages((prev) => [...prev.map((item) => item.id === localId ? { ...item, id: data.user_message_id || item.id, branch_id: data.branch_id || "" } : item), { id: data.assistant_message_id || `mobile-ai-${Date.now()}`, role: "assistant", content: data.answer || "", references: data.references || [], parent_message_id: data.user_message_id || null, branch_id: data.branch_id || "", created_at: new Date().toISOString() }]); await loadHistory(); } catch (reason) { setError(reason.message || "AI 服务调用失败"); } finally { setLoading(false); } };
  const startEdit = (message) => { setMenu(null); setEditingId(String(message.id)); setEditingText(message.content || ""); inputRef.current?.focus(); };
  const commitEdit = async (message) => { const text = editingText.trim(); if (!text) return; setEditingId(""); setEditingText(""); await send(text, { sourceId: message.id, branchId: message.branch_id || "" }); };
  const copyMessage = async (message) => { try { await navigator.clipboard?.writeText(message.content || ""); setError("已复制"); } catch { setError("复制失败"); } setMenu(null); };
  const upload = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; setUploading(true); setError(""); try { const form = new FormData(); form.append("file", file); form.append("username", user.username); form.append("subject", exam ? subjectLabel : courseLabel); form.append("save_to_materials", "true"); const response = await fetch(`${API_BASE}/materials/upload`, { method: "POST", credentials: "include", body: form }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "文件上传失败"); setInput((prev) => prev || `请结合文件「${data.filename || file.name}」回答我的问题。`); } catch (reason) { setError(reason.message || "文件上传失败"); } finally { setUploading(false); } };
  const newChat = () => { setSessionId(null); setMessages([]); setInput(""); setMenu(null); };
  return <div className="page mobile-ai-page"><PageHeading eyebrow={exam ? "11408 AI" : course ? `课程 AI · ${MODE_LABELS[route.mode]}` : "普通 AI"} title="AI助手" description="历史对话按当前学习空间自动隔离。" /><section className="mobile-ai-context"><strong>{exam ? subjectLabel : course ? courseLabel : "普通 AI"}</strong><span>{exam ? `科目：${subjectLabel}` : course ? `课程：${courseLabel} · ${MODE_LABELS[route.mode]}` : "独立 AI 服务"}</span>{context.chapter && <span>章节：{context.chapter}</span>}{context.knowledge && <span>知识点：{context.knowledge}</span>}</section><div className="mobile-ai-history"><div className="mobile-ai-history-head"><strong>历史对话</strong><button type="button" onClick={newChat}>新对话</button></div>{loadingHistory ? <small>正在读取历史…</small> : sessions.length ? sessions.slice(0, 8).map((session) => <button type="button" key={session.id} className={sessionId === session.id ? "is-active" : ""} onClick={() => loadSession(session.id)}><span>{session.title || "未命名对话"}</span><small>{session.subject || session.exam_subject || "AI"}</small></button>) : <small>暂无历史对话</small>}</div><div className="mobile-ai-messages" ref={messagesRef}>{messages.length === 0 && !loading ? <div className="mobile-ai-empty"><Icon name="ai" /><strong>开始你的提问</strong><span>当前空间上下文会自动携带。</span></div> : messages.map((message) => <article key={`${message.role}-${message.id}`} className={`mobile-ai-message ${message.role === "user" ? "is-user" : "is-assistant"}`} onContextMenu={(event) => { if (message.role === "user") { event.preventDefault(); setMenu({ id: message.id, x: event.clientX, y: event.clientY }); } }}><div className="mobile-ai-message-role">{message.role === "user" ? "我" : "AI"}</div>{editingId === String(message.id) ? <div className="mobile-ai-edit"><textarea value={editingText} onChange={(event) => setEditingText(event.target.value)} autoFocus /><div><button type="button" onClick={() => { setEditingId(""); setEditingText(""); }}>取消</button><button type="button" onClick={() => commitEdit(message)}>提交</button></div></div> : <div className="mobile-ai-message-body"><p>{message.content}</p>{message.references?.length > 0 && <small>包含 {message.references.length} 条参考资料</small>}</div>}{menu?.id === message.id && <div className="mobile-ai-message-menu"><button type="button" onClick={() => startEdit(message)}>编辑</button><button type="button" onClick={() => send(message.content, { sourceId: message.id, branchId: message.branch_id || "" })}>重新生成</button><button type="button" onClick={() => send(message.content, { sourceId: message.id, branchId: `mobile-branch-${Date.now()}` })}>创建分支</button><button type="button" onClick={() => copyMessage(message)}>复制</button></div>}</article>)}</div>{error && <div className="inline-error">{error}</div>}<form className="mobile-ai-composer" onSubmit={(event) => { event.preventDefault(); send(); }}><input ref={fileRef} type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.pptx,.txt,.md,.markdown,.py,.java,.c,.cpp,.h,.hpp,.js,.jsx,.ts,.tsx,.html,.htm,.css,.json,.xml,.yaml,.yml,.sql,.sh,.bash,.go,.rs,.php,.rb" onChange={upload} /><button type="button" className="mobile-ai-tool" onClick={() => fileRef.current?.click()} disabled={uploading}>{uploading ? "…" : "＋"}</button><textarea ref={inputRef} value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); send(); } }} placeholder="输入问题…" rows={1} /><button type="submit" className="primary-button" disabled={loading || !input.trim()}>发送</button></form></div>;
}

function questionOptions(question) { const raw = question?.options; if (!raw) return []; if (Array.isArray(raw)) return raw.map((item, index) => Array.isArray(item) ? [item[0], item[1]] : [String.fromCharCode(65 + index), item]); if (typeof raw === "object") return Object.entries(raw); try { const parsed = JSON.parse(raw); return questionOptions({ options: parsed }); } catch { return String(raw).split(/\n|[,，]/).map((item, index) => [String.fromCharCode(65 + index), item.trim()]).filter((item) => item[1]); } }
function CourseChapterPractice({ route, course, user }) { const id = courseId(course); const name = courseName(course); const state = useResource(() => Promise.all([getJson(`/knowledge-map?course_id=${encodeURIComponent(id)}&username=${encodeURIComponent(user.username)}`), getJson(`/practice/questions?username=${encodeURIComponent(user.username)}&course_id=${encodeURIComponent(id)}`).catch(() => null)]).then(([map, bank]) => ({ map, questions: safeArray(bank?.questions) })), [id, user.username]); const chapters = safeArray(state.data?.map?.chapters); const [chapterTitle, setChapterTitle] = useState(route.chapter || ""); const [questionIndex, setQuestionIndex] = useState(0); const [answers, setAnswers] = useState({}); const [results, setResults] = useState({}); const [submitting, setSubmitting] = useState(false); const activeChapter = chapters.find((chapter) => (chapter.title || chapter.name) === chapterTitle) || chapters[0]; const activeTitle = activeChapter?.title || activeChapter?.name || chapterTitle; const chapterPoints = knowledgeLeaves(activeChapter?.children || [], activeTitle); const pointIds = new Set(chapterPoints.flatMap((point) => [point.id, point.code]).filter(Boolean).map(String)); const allQuestions = safeArray(state.data?.questions); const chapterQuestions = allQuestions.filter((question) => { const selectedKnowledge = route.knowledge || route.knowledgeId; if (selectedKnowledge) return [question.knowledge_point_id, question.knowledge_point_code, question.knowledge_point_title].filter(Boolean).map(String).includes(String(selectedKnowledge)); if (!activeChapter || pointIds.size === 0) return true; const keys = [question.knowledge_point_id, question.knowledge_point_code, question.chapter, question.chapter_name].filter(Boolean).map(String); return keys.some((key) => pointIds.has(key) || key === String(activeTitle)); }); const question = chapterQuestions[questionIndex] || chapterQuestions[0]; const questionId = question?.id; const answer = questionId ? answers[questionId] || "" : ""; const result = questionId ? results[questionId] : null; const setAnswer = (value) => setAnswers((previous) => ({ ...previous, [questionId]: value })); const submit = async () => { if (!questionId || !answer || submitting) return; setSubmitting(true); try { const response = await fetch(`${API_BASE}/practice/questions/${encodeURIComponent(questionId)}/attempts`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, question_id: questionId, user_answer: answer }) }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.detail || "提交答案失败"); setResults((previous) => ({ ...previous, [questionId]: data.attempt || data })); } catch (error) { setResults((previous) => ({ ...previous, [questionId]: { error: error.message || "提交答案失败" } })); } finally { setSubmitting(false); } }; if (state.status !== "success") return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[route.mode]}`} title="章节练习" description={`${name} · 题目来自 PC 题库`} /><AsyncState state={state} emptyTitle="暂无章节练习" emptyDescription="PC 端当前没有返回可练习题目。" /></div>; return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[route.mode]}`} title="章节练习" description={`${name} · 题目来自 PC 题库`} /><label className="mobile-select-label"><span>章节</span><select value={activeTitle} onChange={(event) => { setChapterTitle(event.target.value); setQuestionIndex(0); }}><option value="">全部章节</option>{chapters.map((chapter, index) => <option key={chapter.code || chapter.id || index} value={chapter.title || chapter.name}>{chapter.title || chapter.name}</option>)}</select></label>{!question ? <div className="empty-course"><strong>暂无章节练习题</strong><span>PC 端当前没有与本章节匹配的题目。</span></div> : <section className="mobile-practice-question"><div className="mobile-question-meta">第 {questionIndex + 1} / {chapterQuestions.length} 题 · {question.type || "练习题"}</div><h2>{question.stem || question.title}</h2><div className="mobile-question-options">{questionOptions(question).map(([key, value]) => <button type="button" key={key} className={answer === key ? "is-selected" : ""} disabled={Boolean(result && !result.error)} onClick={() => setAnswer(key)}><strong>{key}</strong><span>{value}</span></button>)}{questionOptions(question).length === 0 && <input className="mobile-answer-input" value={answer} onChange={(event) => setAnswer(event.target.value)} placeholder="输入答案" disabled={Boolean(result && !result.error)} />}</div>{result?.error && <div className="inline-error">{result.error}</div>}{result && !result.error && <div className={`mobile-practice-result ${attemptCorrect(result) === true ? "is-correct" : attemptCorrect(result) === false ? "is-wrong" : "is-unanswered"}`}><strong>{attemptCorrect(result) === true ? "回答正确" : attemptCorrect(result) === false ? "回答错误" : "已提交，未返回判定"}</strong><span>标准答案：{result.correct_answer || result.answer || question.answer || "暂无返回"}</span><p>{result.explanation || result.analysis || question.explanation || question.analysis || "暂无解析"}</p></div>}{!result && <button type="button" className="primary-button mobile-submit-button" onClick={submit} disabled={!answer || submitting}>{submitting ? "提交中…" : "提交答案"}</button>}<div className="mobile-question-nav"><button type="button" className="secondary-button" disabled={questionIndex <= 0} onClick={() => setQuestionIndex((value) => value - 1)}>上一题</button><button type="button" className="secondary-button" disabled={questionIndex >= chapterQuestions.length - 1} onClick={() => setQuestionIndex((value) => value + 1)}>下一题</button></div></section>}</div>; }
function PracticeHome({ route, course, user }) { const name = course ? courseName(course) : EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject; const exam = route.space === EXAM; const examData = useResource(() => exam ? Promise.all([getJson(`/exam/11408/${route.subject}/past-papers`).catch(() => ({ years: [] })), getJson(`/exam/11408/${route.subject}/wrong-questions?username=${encodeURIComponent(user.username)}`).catch(() => ({ items: [] })), getJson(`/exam/11408/${route.subject}/ai-questions?username=${encodeURIComponent(user.username)}`).catch(() => ({ items: [] }))]).then(([past, wrong, ai]) => ({ past, wrong, ai })) : Promise.resolve(null), [exam, route.subject, user.username]); const entries = exam ? [{ type: "past-paper", title: "真题练习", icon: "practice", count: safeArray(examData.data?.past?.years).length ? `${safeArray(examData.data?.past?.years).length} 个年份` : "暂无年份" }, { type: "wrong", title: "错题练习", icon: "knowledge", count: `${safeArray(examData.data?.wrong?.items).length} 题` }, { type: "ai", title: "AI出题", icon: "ai", count: `${safeArray(examData.data?.ai?.items).length} 题` }] : [{ type: "chapter", title: "章节练习", icon: "practice", count: "按章节进入" }, { type: "knowledge", title: "知识点练习", icon: "knowledge", count: "按知识点进入" }]; const openEntry = (type) => { const base = exam ? `/m/exam11408/${route.subject}/practice` : coursePath(route.mode, route.courseId, "/practice"); go(`${base}?type=${type}${route.chapter ? `&chapter=${encodeURIComponent(route.chapter)}` : ""}`); }; const selected = entries.find((entry) => entry.type === route.practiceType); const selectedData = selected?.type === "past-paper" ? safeArray(examData.data?.past?.years).map((year) => `${year} 年真题`) : selected?.type === "wrong" ? safeArray(examData.data?.wrong?.items).slice(0, 8).map((item) => item.stem || item.question_title || "错题") : selected?.type === "ai" ? safeArray(examData.data?.ai?.items).slice(0, 8).map((item) => item.stem || item.question_title || "AI题目") : []; return <div className="page"><PageHeading eyebrow={exam ? "11408考研中心" : `课程学习 · ${MODE_LABELS[route.mode]}`} title="练习" description={`${name} · ${exam ? "真实题库入口" : "课程练习入口"}`} />{examData.status === "loading" && exam ? <div className="inline-state">正在读取 PC 端练习数据…</div> : <div className="practice-list">{entries.map((entry) => <ActionRow key={entry.type} icon={entry.icon} title={entry.title} description={`${entry.count} · 绑定当前${exam ? "科目" : "课程"}：${name}`} onClick={() => openEntry(entry.type)} />)}</div>}{selected && <section className="practice-data-panel"><SectionTitle title={selected.title} />{selectedData.length ? selectedData.map((item, index) => <div className="practice-data-row" key={`${selected.type}-${index}`}><span>{index + 1}</span><strong>{item}</strong></div>) : <div className="empty-course"><strong>暂无数据</strong><span>PC 端当前没有可显示的{selected.title}。</span></div>}</section>}</div>; }
function ExamStudyPlanMobile({ user, subject }) { const name = EXAM_SUBJECTS.find(([id]) => id === subject)?.[1] || subject; const state = useResource(() => getJson(`/exam/11408/subjects/${encodeURIComponent(subject)}/study-plan?username=${encodeURIComponent(user.username)}`), [subject, user.username]); const data = state.data || {}; const tasks = safeArray(data.tasks || data.items); return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="学习计划" description="计划状态来自 PC 端，当前科目独立同步。" />{state.status === "success" && tasks.length ? <div className="task-list">{tasks.map((task, index) => <article className="task-card" key={task.id || task.code || index}><span className="task-mark"><Icon name="book" /></span><span><strong>{task.title || task.name || "学习任务"}</strong><small>{task.status || task.state || "待完成"}</small></span></article>)}</div> : <AsyncState state={state} emptyTitle="暂无学习计划" emptyDescription="PC 端当前没有为该科目创建学习计划。" />}</div>; }

function ExamSelect() { return <div className="page"><PageHeading title="11408考研中心" description="选择科目进入独立的 11408 体系。" /><SectionTitle title="选择科目" /><div className="selection-list">{EXAM_SUBJECTS.map(([id, name]) => <button className="selection-card exam-selection" key={id} onClick={() => go(`/m/exam11408/${id}/home`)}><span className="selection-icon"><Icon name="exam" /></span><span><strong>{name}</strong><small>章节、真题、错题、AI、学习计划</small></span><b>›</b></button>)}</div></div>; }
function examMapCourseId(subject) { return `${subject}_11408`; }
function ExamChapters({ user, subject, chapter }) { const name = EXAM_SUBJECTS.find(([id]) => id === subject)?.[1] || subject; const state = useResource(() => getJson(`/knowledge-map?course_id=${encodeURIComponent(examMapCourseId(subject))}&username=${encodeURIComponent(user.username)}`), [subject, user.username]); const chapters = safeArray(state.data?.chapters); const currentChapter = chapter || chapters[0]?.title || ""; return <div className="page"><PageHeading eyebrow={`11408 · ${name}`} title="章节" description="真实章节结构来自 PC 端知识图谱。" />{state.status !== "success" ? <AsyncState state={state} emptyTitle="暂无章节数据" emptyDescription="PC 端还没有为该科目生成章节结构。" /> : chapters.length === 0 ? <div className="empty-course"><strong>暂无章节数据</strong><span>PC 端还没有为该科目生成章节结构。</span></div> : <><section className="chapter-context-card"><Icon name="book" /><div><strong>{currentChapter}</strong><small>科目：{name}</small></div></section><div className="mobile-exam-chapters">{chapters.map((item, index) => <button type="button" key={item.code || item.id || index} className={currentChapter === (item.title || item.name) ? "is-active" : ""} onClick={() => { const next = item.title || item.name || ""; localStorage.setItem("currentExamChapter", next); go(`/m/exam11408/${subject}/chapters?chapter=${encodeURIComponent(next)}`); }}><span>{index + 1}</span><strong>{item.title || item.name}</strong><b>{knowledgeLeaves(item.children || []).length} 个知识点 ›</b></button>)}</div><div className="chapter-action-row"><button className="secondary-button" onClick={() => go(`/m/exam11408/${subject}/practice?chapter=${encodeURIComponent(currentChapter)}`)}>进入练习</button><button className="primary-button" onClick={() => go(`/m/exam11408/${subject}/ai?chapter=${encodeURIComponent(currentChapter)}`)}>进入 AI助手</button></div></>}</div>; }
function ExamHome({ user, subject }) { const name = EXAM_SUBJECTS.find(([id]) => id === subject)?.[1] || subject; const state = useResource(() => getJson(`/knowledge-map?course_id=${encodeURIComponent(examMapCourseId(subject))}&username=${encodeURIComponent(user.username)}`), [subject, user.username]); const chapters = safeArray(state.data?.chapters); return <div className="page"><PageHeading eyebrow="11408考研中心" title="首页" description="当前科目的真实章节与备考入口。" /><ContextBar mode="exam" name={name} onChange={() => go("/m/exam11408")} /><section className="hero-card exam-hero"><div><span className="card-label">当前科目</span><h2>{name}</h2><p>{state.status === "success" ? `${chapters.length} 个章节 · 章节结构来自 PC 端` : "正在读取 PC 端章节结构…"}</p><button className="primary-button" onClick={() => go(`/m/exam11408/${subject}/chapters`)}>查看章节</button></div><div className="hero-orb"><Icon name="exam" /></div></section>{state.status === "success" && chapters.length > 0 && <section className="exam-home-chapter-preview"><SectionTitle title="章节结构" />{chapters.slice(0, 4).map((item, index) => <button key={item.code || item.id || index} onClick={() => go(`/m/exam11408/${subject}/chapters?chapter=${encodeURIComponent(item.title || item.name || "")}`)}><span>{index + 1}</span><strong>{item.title || item.name}</strong><b>›</b></button>)}</section>}<div className="quick-grid"><button onClick={() => go(`/m/exam11408/${subject}/practice`)}><Icon name="practice" /><strong>练习</strong><small>真题、错题、AI出题</small></button><button onClick={() => go(`/m/exam11408/${subject}/ai`)}><Icon name="ai" /><strong>AI助手</strong><small>当前科目 AI</small></button></div></div>; }
function Profile({ user, onProfileUpdate }) { const [modal, setModal] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const [nickname, setNickname] = useState(user.nickname || ""); const [password, setPassword] = useState({ old_password: "", new_password: "", confirm_password: "" }); const [email, setEmail] = useState({ email: "", code: "" }); const fileRef = useRef(null); const name = nickname || user.username || "学习者"; const avatar = user.avatar_url || (user.avatar && String(user.avatar).includes(".") ? `${API_BASE}/me/avatar/${user.avatar}` : ""); const close = () => { setModal(""); setError(""); setMessage(""); }; const update = (profile) => { const next = { ...user, ...profile }; localStorage.setItem("ai_study_platform_user", JSON.stringify(next)); onProfileUpdate(next); }; const uploadAvatar = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; setBusy(true); setError(""); try { const fd = new FormData(); fd.append("file", file); fd.append("username", user.username); const data = await getJson("/me/avatar", { method: "POST", body: fd }); update(data.profile || { avatar_url: data.avatar_url }); setMessage("头像已更新"); } catch (e) { setError(e.message || "头像上传失败"); } finally { setBusy(false); } }; const saveNickname = async () => { if (!nickname.trim()) return setError("昵称不能为空"); setBusy(true); setError(""); try { const data = await getJson(`/me/profile?username=${encodeURIComponent(user.username)}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ nickname: nickname.trim() }) }); update(data.profile || { nickname: nickname.trim() }); setMessage("昵称已更新"); } catch (e) { setError(e.message || "昵称保存失败"); } finally { setBusy(false); } }; const savePassword = async () => { if (password.new_password !== password.confirm_password) return setError("两次输入的新密码不一致"); setBusy(true); setError(""); try { await getJson(`/me/password?username=${encodeURIComponent(user.username)}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(password) }); setPassword({ old_password: "", new_password: "", confirm_password: "" }); setMessage("密码已修改"); } catch (e) { setError(e.message || "密码修改失败"); } finally { setBusy(false); } }; const bindEmail = async () => { setBusy(true); setError(""); try { const data = await getJson(`/me/email/verify?username=${encodeURIComponent(user.username)}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(email) }); update(data.profile || { email: email.email }); setMessage("邮箱已绑定"); } catch (e) { setError(e.message || "邮箱绑定失败"); } finally { setBusy(false); } }; const sendCode = async () => { setBusy(true); setError(""); try { await getJson(`/me/email/send-code?username=${encodeURIComponent(user.username)}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: email.email }) }); setMessage("验证码已发送"); } catch (e) { setError(e.message || "验证码发送失败"); } finally { setBusy(false); } }; return <div className="page profile-page"><PageHeading title="我的" /><section className="profile-head"><div className="profile-avatar">{avatar ? <img src={avatar} alt="头像" /> : name.slice(0, 1)}</div><div><h2>{name}</h2><p>{user.email || "学习者账号"}</p></div><span className="profile-plan-badge">会员状态</span></section><SectionTitle title="学习空间" /><div className="space-stack"><button className="space-card course-space-card" onClick={() => go("/m/course")}><span className="space-card-icon"><Icon name="book" /></span><span className="space-card-copy"><strong>课程学习</strong><small>平日学习与考前突击</small><b>选择学习模式 ›</b></span></button><div className="space-separator"><Icon name="lock" /> 两个系统独立，数据不互通</div><button className="space-card exam-space-card" onClick={() => go("/m/exam11408")}><span className="space-card-icon"><Icon name="exam" /></span><span className="space-card-copy"><strong>11408考研中心</strong><small>真题、错题、AI助手、计划</small><b>选择科目 ›</b></span></button></div><SectionTitle title="服务" /><div className="settings-list"><ActionRow icon="quota" title="额度使用" description="查看真实使用量" onClick={() => go("/m/profile/quota")} /><ActionRow icon="shop" title="商城" description="会员套餐、课程包、11408套餐" onClick={() => go("/m/profile/shop")} /></div><SectionTitle title="账号设置" /><div className="settings-list"><ActionRow icon="user" title="修改头像" onClick={() => fileRef.current?.click()} /><ActionRow icon="user" title="修改昵称" onClick={() => { setModal("nickname"); setMessage(""); }} /><ActionRow icon="lock" title="修改密码" onClick={() => { setModal("password"); setMessage(""); }} /><ActionRow icon="user" title="绑定邮箱" onClick={() => { setModal("email"); setMessage(""); }} /></div><input ref={fileRef} hidden type="file" accept="image/jpeg,image/png,image/webp" onChange={uploadAvatar} />{(modal || message || error) && <div className="mobile-modal-backdrop" onClick={close}><section className="mobile-modal" onClick={(event) => event.stopPropagation()}><div className="mobile-modal-head"><strong>{modal === "nickname" ? "修改昵称" : modal === "password" ? "修改密码" : modal === "email" ? "绑定邮箱" : "账号提示"}</strong><button type="button" onClick={close}>×</button></div>{error && <div className="inline-error">{error}</div>}{message && <div className="inline-success">{message}</div>}{modal === "nickname" && <><input value={nickname} onChange={(e) => setNickname(e.target.value)} placeholder="输入昵称" /><button className="primary-button" disabled={busy} onClick={saveNickname}>保存</button></>}{modal === "password" && <><input type="password" value={password.old_password} onChange={(e) => setPassword({ ...password, old_password: e.target.value })} placeholder="当前密码" /><input type="password" value={password.new_password} onChange={(e) => setPassword({ ...password, new_password: e.target.value })} placeholder="新密码" /><input type="password" value={password.confirm_password} onChange={(e) => setPassword({ ...password, confirm_password: e.target.value })} placeholder="确认新密码" /><button className="primary-button" disabled={busy} onClick={savePassword}>确认修改</button></>}{modal === "email" && <><input type="email" value={email.email} onChange={(e) => setEmail({ ...email, email: e.target.value })} placeholder="邮箱地址" /><div className="modal-inline"><input value={email.code} onChange={(e) => setEmail({ ...email, code: e.target.value })} placeholder="验证码" /><button type="button" onClick={sendCode} disabled={busy}>发送验证码</button></div><button className="primary-button" disabled={busy} onClick={bindEmail}>确认绑定</button></>}</section></div>}</div>; }

function MobileMembership({ user }) { const summary = useResource(() => getJson(`/membership/summary?username=${encodeURIComponent(user.username)}`), [user.username]); const catalogs = useResource(() => Promise.all(["course_learning", "exam_11408"].map((key) => getJson(`/membership/catalog?service_key=${key}`))), [user.username]); const plan = summary.data?.effective_plan; return <div className="page"><PageHeading title="会员中心" description="当前账号的真实套餐与权益。" />{summary.status !== "success" ? <AsyncState state={summary} /> : <section className="info-card"><span className="card-label">当前套餐</span><h2>{plan?.plan_label || plan?.plan_name || summary.data?.current_plan || "免费"}</h2><p>{summary.data?.is_member ? "会员有效" : "当前为免费方案"}</p></section>}<SectionTitle title="权益" />{summary.status === "success" && <div className="benefit-grid"><div><strong>{summary.data.limits?.daily_ai_limit ?? "—"}</strong><small>每日 AI 额度</small></div><div><strong>{summary.data.limits?.daily_upload_limit ?? "—"}</strong><small>每日上传额度</small></div></div>}<SectionTitle title="可用套餐" />{catalogs.status === "success" ? catalogs.data.flatMap((catalog) => catalog.plans || []).map((item) => <div className="plan-card" key={`${item.service_key || "service"}-${item.code || item.plan_code || item.name}`}><strong>{item.name || item.plan_label || item.plan_code}</strong><span>{item.description || item.perks || "套餐权益"}</span><b>{item.price_yuan != null ? `¥${item.price_yuan}` : "免费"}</b></div>) : <AsyncState state={catalogs} emptyTitle="暂无套餐" emptyDescription="暂时无法读取会员目录。" />}</div>; }

function MobileQuota({ user }) { const state = useResource(() => getJson(`/me/quota?username=${encodeURIComponent(user.username)}`), [user.username]); const labels = { chat: "AI 对话", question_generate: "AI 出题", code_analyze: "代码分析", challenge_generate: "挑战生成", learning_diagnosis: "学习诊断", knowledge_generate: "知识点生成", material_link_recommend: "资料关联推荐", learning_plan_generate: "学习计划", learning_report_generate: "学习报告" }; const categories = { "AI 学习": ["chat", "question_generate", "knowledge_generate"], "课程工具": ["learning_plan_generate", "learning_report_generate", "learning_diagnosis"], "资料与编程": ["material_link_recommend", "code_analyze", "challenge_generate"] }; const entries = Object.entries(state.data?.feature_limits || {}); return <div className="page"><PageHeading title="额度使用" description="按学习场景查看当前账号的真实使用量。" />{state.status !== "success" ? <AsyncState state={state} emptyTitle="暂无额度数据" emptyDescription="请稍后重试。" /> : <><section className="info-card"><span className="card-label">当前套餐</span><h2>{state.data.plan?.plan_label || state.data.plan?.plan_code || "免费"}</h2></section><div className="quota-categories">{Object.entries(categories).map(([category, keys]) => { const items = entries.filter(([key]) => keys.includes(key)); if (!items.length) return null; return <section className="quota-category" key={category}><SectionTitle title={category} /><div className="quota-category-grid">{items.map(([key, item]) => <div className="quota-card" key={key}><div><strong>{labels[key] || "学习能力"}</strong><small>已使用 {item.used ?? 0} · 剩余 {item.remaining ?? 0}</small></div><b>{item.limit >= 999999 ? "不限" : item.limit ?? "—"}</b></div>)}</div></section>; })}<section className="quota-category"><SectionTitle title="资料上传" /><div className="quota-card"><div><strong>资料上传数量</strong><small>已使用 {state.data.upload_limits?.material_upload_count?.used ?? 0}</small></div><b>{state.data.upload_limits?.material_upload_count?.limit ?? "—"}</b></div></section></div></>}</div>; }

function MobileShop() { const [paymentNotice, setPaymentNotice] = useState(""); const state = useResource(() => Promise.all([getJson("/membership/catalog?service_key=course_learning"), getJson("/membership/catalog?service_key=exam_11408"), getJson("/course-learning/packages")]), []); const isPaid = (item) => { const code = String(item.plan_code || item.plan || item.code || item.slug || "").toLowerCase(); return code !== "free" && code !== "basic_free" && !code.includes("free"); }; return <div className="page"><PageHeading title="商城" description="仅展示服务端返回的真实付费套餐。免费用户当前套餐显示在额度页面。" />{state.status !== "success" ? <AsyncState state={state} emptyTitle="暂无套餐" emptyDescription="暂时无法读取商城数据。" /> : <>{state.data.map((group, index) => { const plans = (group.plans || []).filter(isPaid); if (!plans.length) return null; const isCoursePackageCatalog = plans.some((item) => item.plan); const title = group.service_key === "exam_11408" ? "11408套餐" : isCoursePackageCatalog ? "课程包" : "会员套餐"; return <section key={`${group.service_key || "catalog"}-${index}`}><SectionTitle title={title} />{plans.map((item) => <div className="plan-card" key={`${group.service_key || "catalog"}-${item.code || item.plan_code || item.plan || item.name}`}><div><strong>{item.name || item.plan_label || item.plan_code || item.plan}</strong><span>{item.description || item.perks || "真实套餐权益"}</span></div><b>{item.price_yuan != null ? `¥${item.price_yuan}` : "—"}</b><button type="button" onClick={() => setPaymentNotice("支付功能暂未开放，未创建订单。")}>购买</button></div>)}{group.payment_notice && <p className="payment-notice">{group.payment_notice}；移动端暂不发起订单。</p>}</section>; })}{paymentNotice && <div className="inline-success shop-payment-notice">{paymentNotice}</div>}</>}</div>; }
export default function MobileApp() { const [user, setUser] = useState(readUser); const [path, setPath] = useState(window.location.pathname + window.location.search); const route = useMemo(() => routeWithContext(path), [path]); const courseState = useResource(() => route.courseId ? getJson(`/course-learning/courses?username=${encodeURIComponent(user.username)}`).then((data) => { const requested = decodeURIComponent(route.courseId); return safeArray(data.courses).find((item) => courseId(item) === requested); }) : Promise.resolve(null), [user.username, route.courseId]); useEffect(() => { const update = () => setPath(window.location.pathname + window.location.search); window.addEventListener("popstate", update); return () => window.removeEventListener("popstate", update); }, []); useEffect(() => { if (route.redirectTo && path !== route.redirectTo) go(route.redirectTo); }, [path, route.redirectTo]); useEffect(() => { if (!route.courseId || courseState.status !== "success") return; if (!courseState.data) { go(`/m/course/${route.mode || "daily"}`); return; } const actualMode = courseLearningMode(courseState.data); if (actualMode !== route.mode) { const suffix = route.page === "course-knowledge" ? "/knowledge" : route.page === "course-practice" ? "/practice" : route.page === "course-plan" ? "/plan" : route.page === "ai" ? "/ai" : "/home"; go(coursePath(actualMode, courseId(courseState.data), suffix)); } }, [courseState.data, courseState.status, route.courseId, route.mode, route.page]); if (!user.username && !user.nickname) return <MobileAuth onAuthenticated={setUser} />; const course = courseState.data; const contextLabel = course ? `${courseName(course)} · ${courseLearningModeLabel(course)}` : route.space === EXAM && route.subject ? (EXAM_SUBJECTS.find(([id]) => id === route.subject)?.[1] || route.subject) : ""; const page = route.page === "profile" ? <Profile user={user} onProfileUpdate={setUser} /> : route.page === "profile-membership" ? <MobileMembership user={user} /> : route.page === "profile-quota" ? <MobileQuota user={user} /> : route.page === "profile-shop" ? <MobileShop /> : route.page === "course-mode" ? <CourseModeSelect /> : route.page === "course-daily" ? <CourseDaily user={user} /> : route.page === "course-exam" ? <CourseExam user={user} /> : route.page === "exam-select" ? <ExamSelect /> : route.page === "exam-chapters" ? <ExamChaptersMobile user={user} subject={route.subject} chapter={route.chapter} /> : route.page === "course-home" ? (course ? <CourseHome course={course} mode={route.mode} user={user} /> : <AsyncState state={courseState} emptyTitle="暂无课程" emptyDescription="请在电脑端添加课程，手机端自动同步。" />) : route.page === "course-knowledge" ? (course ? <CourseKnowledge user={user} course={course} mode={route.mode} /> : <AsyncState state={courseState} emptyTitle="暂无课程" emptyDescription="请先从平日学习或考前突击进入课程。" />) : route.page === "course-plan" ? (course ? <CoursePlan user={user} course={course} mode={route.mode} /> : <AsyncState state={courseState} emptyTitle="暂无课程" emptyDescription="请在电脑端课程学习系统中创建计划。" />) : route.page === "course-exam-task" ? (course ? <CourseExamTask user={user} course={course} route={route} /> : <AsyncState state={courseState} emptyTitle="暂无考试任务" emptyDescription="请在电脑端课程学习系统中配置考前突击任务。" />) : route.page === "ai" || route.page === "exam-ai" ? <AIHome route={route} course={course} /> : route.page === "course-practice" ? (course ? <CourseChapterPractice route={route} course={course} user={user} /> : <AsyncState state={courseState} emptyTitle="暂无课程" emptyDescription="请先从课程列表进入课程。" />) : route.page === "exam-practice" ? <ExamPracticeMobile route={route} user={user} /> : route.page === "exam-home" ? <ExamHome user={user} subject={route.subject} /> : <CourseModeSelect />; return <AppShell route={route} user={user} contextLabel={contextLabel}>{page}</AppShell>; }
const legacyMobileRouteFor = routeFor;
routeFor = (pathname) => { const route = legacyMobileRouteFor(pathname); return route.page === "exam-plan" ? { ...route, page: "exam-home" } : route; };
const LegacyExamHome = ExamHome;
ExamHome = (props) => window.location.pathname.endsWith("/plan") ? <ExamStudyPlanMobile user={props.user} subject={props.subject} /> : <LegacyExamHome {...props} />;
const legacyMobileGetJson = getJson;
getJson = (path, options = {}) => { if (path.includes("/wrong-questions/") && path.endsWith("/mastered") && options.method === "PATCH") { const body = (() => { try { return JSON.parse(options.body || "{}"); } catch { return {}; } })(); const nextOptions = { ...options, body: JSON.stringify({ ...body, mastered: body.mastered ?? true }) }; return legacyMobileGetJson(path, nextOptions); } return legacyMobileGetJson(path, options); };

function MobileCoursePracticeV87({ route, course, user }) {
  const id = courseId(course);
  const name = courseName(course);
  const state = useResource(() => Promise.all([
    getJson(`/knowledge-map?course_id=${encodeURIComponent(id)}&username=${encodeURIComponent(user.username)}`),
    getJson(`/course-learning/practice/workbook?username=${encodeURIComponent(user.username)}&course_id=${encodeURIComponent(id)}&status=all`),
  ]).then(([map, workbook]) => ({ map, items: safeArray(workbook.items) })), [id, user.username]);
  const chapters = safeArray(state.data?.map?.chapters);
  const [chapter, setChapter] = useState(route.chapter || "");
  const [selected, setSelected] = useState(null);
  const [attemptId, setAttemptId] = useState("");
  const [answer, setAnswer] = useState("");
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);
  const activeChapter = chapters.find((item) => (item.title || item.name) === chapter);
  const points = new Set(knowledgeLeaves(activeChapter?.children || [], chapter).flatMap((item) => [item.id, item.code]).filter(Boolean).map(String));
  const items = safeArray(state.data?.items).filter((item) => {
    const knowledge = route.knowledge || route.knowledgeId;
    if (knowledge) return [item.knowledge_point_id, item.knowledge_point_code, item.knowledge_point_title].filter(Boolean).map(String).includes(String(knowledge));
    if (!chapter || !points.size) return true;
    return [item.knowledge_point_id, item.knowledge_point_code, item.knowledge_point_path].filter(Boolean).map(String).some((key) => points.has(key) || key === chapter);
  });
  const start = async (item) => {
    setBusy(true); setResult(null);
    try { const data = await getJson(`/course-learning/practice/workbook/${encodeURIComponent(item.id)}/attempts`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username }) }); setSelected(data.question || item); setAttemptId(String(data.attempt_id || "")); setAnswer(""); }
    catch (error) { setResult({ error: error.message || "开始练习失败" }); } finally { setBusy(false); }
  };
  const generate = async () => {
    const point = knowledgeLeaves(activeChapter?.children || [], chapter)[0];
    if (!point) return;
    setBusy(true); setResult(null);
    try { const data = await getJson("/course-learning/practice/generate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, course_id: id, course_name: name, chapter, knowledge_point_code: point.code, knowledge_point_title: knowledgeTitle(point), difficulty: "基础" }) }); setSelected(data.question); setAttemptId(String(data.attempt_id || "")); setAnswer(""); }
    catch (error) { setResult({ error: error.message || "生成练习失败" }); } finally { setBusy(false); }
  };
  const submit = async () => {
    if (!attemptId || !answer || busy) return;
    setBusy(true);
    try { const data = await getJson(`/course-learning/practice/${encodeURIComponent(attemptId)}/submit`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: user.username, answer }) }); setResult(data.result || data); }
    catch (error) { setResult({ error: error.message || "提交答案失败" }); } finally { setBusy(false); }
  };
  if (state.status !== "success") return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[route.mode]}`} title="章节练习" /><AsyncState state={state} emptyTitle="暂无章节练习" emptyDescription="PC 端当前没有返回可练习题目。" /></div>;
  if (selected) return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[route.mode]}`} title="章节练习" description="答题、判题和解析来自 PC 端课程练习接口。" /><MobileQuestion question={selected} answer={answer} onAnswer={setAnswer} disabled={Boolean(result && !result.error)} />{result?.error && <div className="inline-error">{result.error}</div>}{result && !result.error && <div className={`mobile-practice-result ${result.correct ? "is-correct" : "is-wrong"}`}><strong>{result.correct ? "回答正确" : "回答错误"}</strong><span>标准答案：{result.standard_answer || "暂无返回"}</span><p>{result.analysis || "暂无解析"}</p></div>}{!result && <button className="primary-button" disabled={!answer || busy} onClick={submit}>{busy ? "提交中…" : "提交答案"}</button>}<button className="secondary-button" onClick={() => { setSelected(null); setAttemptId(""); setResult(null); }}>返回题册</button></div>;
  return <div className="page"><PageHeading eyebrow={`课程学习 · ${MODE_LABELS[route.mode]}`} title="章节练习" description={`${name} · 题册来自 PC 端`} /><label className="mobile-select-label"><span>章节</span><select value={chapter} onChange={(event) => setChapter(event.target.value)}><option value="">全部章节</option>{chapters.map((item, index) => <option key={item.code || item.id || index} value={item.title || item.name}>{item.title || item.name}</option>)}</select></label>{items.length ? <div className="practice-data-panel">{items.map((item, index) => <article className="practice-data-row" key={item.id || index}><span>{index + 1}</span><strong>{item.stem || item.title || "练习题"}</strong><button className="secondary-button" disabled={busy} onClick={() => start(item)}>{item.attempt_count ? "重新练习" : "开始练习"}</button></article>)}</div> : <div className="empty-course"><strong>暂无章节练习题</strong><span>PC 端当前没有与当前筛选条件匹配的题目。</span>{chapter && <button className="primary-button" disabled={busy} onClick={generate}>{busy ? "生成中…" : "生成第一道题"}</button>}</div>}</div>;
}

CourseChapterPractice = MobileCoursePracticeV87;

const workspaceBaseRouteFor = routeFor;
routeFor = (pathname) => {
  const route = workspaceBaseRouteFor(pathname);
  const parts = pathname.split("?")[0].split("/").filter(Boolean);
  if (parts[0] !== "m") return route;
  if (parts[1] === "course") {
    if (!parts[2] || !["daily", "exam"].includes(parts[2])) return { page: "course-mode", space: COURSE, redirectTo: "/m/course" };
    const mode = parts[2];
    const listPath = `/m/course/${mode}`;
    const invalidChild = ["home", "knowledge", "practice", "plan", "ai", "task"].includes(parts[3] || "") && !parts[4];
    if (invalidChild) return { page: mode === "daily" ? "course-daily" : "course-exam", space: COURSE, mode, redirectTo: listPath };
    if (!parts[3]) return route;
    if (!parts[4]) return { ...route, redirectTo: coursePath(mode, parts[3], "/home") };
    if (!["home", "knowledge", "practice", "plan", "ai"].includes(parts[4])) return { ...route, redirectTo: coursePath(mode, parts[3], "/home") };
    return route;
  }
  if (parts[1] === "exam11408") {
    const listPath = "/m/exam11408";
    const knownSubject = EXAM_SUBJECTS.some(([id]) => id === parts[2]);
    const missingSubjectChild = ["home", "chapters", "practice", "ai", "plan"].includes(parts[2] || "");
    if (missingSubjectChild) return { page: "exam-select", space: EXAM, redirectTo: listPath };
    if (!parts[2]) return route;
    if (!knownSubject) return { page: "exam-select", space: EXAM, redirectTo: listPath };
    if (!parts[3]) return { ...route, redirectTo: `/m/exam11408/${parts[2]}/home` };
    if (!["home", "chapters", "practice", "ai"].includes(parts[3])) return { ...route, redirectTo: `/m/exam11408/${parts[2]}/home` };
  }
  return route;
};
